insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "8e245881-b9ed-4661-a1cc-c4ea3ae07e52", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 4, "content": "Maddie Duffy (07:42): Yeah, so I inherited our ambassador program when I started, and a lot of the people that are in the ambassador program have had longstanding relationships with different employees at Mystery Ranch or within the Bozeman community because when we started, it was pretty small, and I think Mystery Ranch was one of the first brands to bring on an ambassador program. We just saw kind of a need for it. And to me, when I took that on, I'm like, well, what is an ambassador program? So I kind of just started from the very top of, let's break this down. And so I did my research of what I was seeing other brands doing and why they even had it. And for us, I'm like, okay, so what defines our ambassador program? And for me, I think it builds credibility to our brand and our products. When someone, especially in 2020, everyone wanted new hobbies, and so they were looking to social media to be like, okay, who's an expert in climbing or who's an expert in hunting? (08:50): And so I think by having an ambassador program of someone who represents brand and your products, it builds credibility. It also tells a story beyond what you are telling. So you're relying on these ambassadors to tell a story about your product. And for us, a backpack is much more than a backpack. We've had people write in and tell us that it's saved someone's life or when they were in the military, they used it as a pillow. And so you hear these stories of people who connect to their backpack. That's much more than just the product itself. And then it also just kind of expands your brand awareness. Maybe our followers aren't the same as one of our ambassador's followers, but in return it's just bringing their followers over to us, so it really expands your brand influence.\n\nCole Heilborn (09:43): Sure. You mentioned that at some point prior to you joining the team, Mr. Ranch saw a need for ambassador program. I guess what was that need and why did the company decide to go down this route?", "token_estimate": 500, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "07:42", "end_timestamp": "09:43", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "ea30291a-2798-4c5d-82e6-34fab8608f3f", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 5, "content": "Maddie Duffy (09:57): Yeah, so my boss actually is the one who started the ambassador program at Mystery Ranch, and I think from his standpoint, he was like, we need to expand our reach. Our company was growing really fast and we needed kind of help because it was only a three man marketing team. And so that's kind of where he saw the help, where it's like, okay, we actually get these extra hands to help push out our brand awareness and push out the reach. And then we also get these people who test our products because our designers, they're not the expert in the field. Some of them have never climbed before. So then that's when we rely on our ambassadors who are excellent climbers to be like, Hey, this actually would be really great in the field if you move to the strap over here or you added this buckle X, Y, and Z.\n\nCole Heilborn (10:47): I feel like there's kind of three phrases, the three words that pop up in the industry today, ambassador, athlete and influencer, what are the differences? Are they the same? How do they interconnect? I guess? Do you have a definition that you look at?\n\nMaddie Duffy (11:04): So I don't know if I necessarily have a definition. I think it just depends. It goes from company to company on, you have to define what that means. For us. We didn't want to call them athletes, we wanted to call them ambassadors. And for us, I think that that's a big badge to wear. It's kind of the highest honor, and you just have to define what the expectations are and make sure that your ambassador, your influencer or your athlete, whatever you choose to call them, their goals, align with your goals.", "token_estimate": 410, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "09:57", "end_timestamp": "11:04", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "c965eb49-ea8d-4311-9cfe-5100201d535c", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 6, "content": "Cole Heilborn (11:41): Yeah, interesting. Kind of off topic, but we had some folks over from UST gear on the show last year and they were looking at these three words and looking at trying to build out their ambassador program, but they didn't want to use the word ambassador, athlete or influencer, so they actually made up an entirely new word, or at least new to me. They call all of their ambassadors storytellers, which I think is really unique, something I've not seen before, and I don't know how much the label really influences the relationship, but I think it's cool to see their focus. They said, we really want our ambassadors to be storytellers, and so that's just what they ended up calling them.\n\nMaddie Duffy (12:31): I think that's really cool. And it again goes back to each company has to define what that means. If they want to call their ambassadors, ambassadors, if they want to call them storytellers or athletes or hunters, you have to define what it means to your company. And I think that's really cool because I was saying an ambassador is kind of a storyteller. It's that extra element that you have other than your social media or other than your employees to tell the story of who your brand is,\n\nCole Heilborn (13:03): What makes a successful ambassador? How do you find someone who would be a good fit? I am assuming you're looking at things like their social following, their social reach, but also things like their values and their level of expertise. Maybe for folks who don't have a program set up, what are things that they could consider as they're looking to build their team?", "token_estimate": 404, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "11:41", "end_timestamp": "13:03", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "d5d26f09-8b35-495f-b1c0-d2387a7304c8", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 7, "content": "Maddie Duffy (13:25): So I actually sat down with a few other people in the outdoor industry and just asked them how they run their ambassador program and what works and what doesn't work. And one of them told me, you can't put all of your eggs in one basket. So just because they have a strong social following doesn't mean that they're automatically an ambassador. I think you have to look for other characteristics as well. What's their distribution? Maybe they're really good at trade shows and talking about product knowledge with your consumers. Maybe they do have a YouTube channel or maybe they have an Amazon channel, and then also do they give back to the community? I think that's a huge part, especially for us where we love giving back to the military. We love giving back to all the people who wear our backpacks because they're the ones that are keeping us in business. (14:18): I think the same kind of goes for our ambassadors too, just because you're good at your sport, what else do you do? Do you volunteer at different programs? Are you a part of RMEF? Are you a part of BHA? All of these different nonprofit organizations. The other thing that we look at is are they trustworthy? Do they have a strong reputation? Especially with all of our markets, we want to make sure that that person that we're bringing on as an ambassador can be a strong representation across all of the markets because we do have to be careful in that sense.\n\nCole Heilborn (14:57): Sure. Yeah. So maybe it was a few years ago or 10 years ago, but I feel like ambassadors or influencers were being chosen just because they had a massive following. Let's go find the people who have the million followers on Instagram and try to sign them on. As an influencer, that's starting to change though. The reach, as you said, is no longer the most important part. It's part of the equation, but it's not the most important part. Why is that? Why is changing?", "token_estimate": 487, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "13:25", "end_timestamp": "14:57", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "69ed6734-fe60-4cf1-b5c3-09711c35568e", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 8, "content": "Maddie Duffy (15:30): That is a good question. I think for us, one thing that we've always tried to do with our ambassador program is make sure it's authentic. And I think that's maybe why things are starting to shift is because if someone is just like nilly willy going on Instagram and they're just like, Hey, try these vitamins, but you can tell that it's not authentic. Maybe they don't even use those vitamins, and that was something that was really important for us. We wanted our ambassadors to have a nine to five job, and then their hunting or their skiing was an extra activity that they were doing that they're really good at because that makes it relatable. Not everybody has the luxury of being able to go hunting all day for their full-time job. So it's like the everyday folks want to look up to someone that they can relate to and it's authentic, and I think that's kind of where that shift is happening. I always use this analogy, but I watch a lot of the Bachelor and the Bachelorette and my friends and I, we always joke about afterwards, all of these people become Instagram influencers because they're like, look at all these followers that I now have and these vitamins that I've never used, but I'm going to say that they look good. And I think that's fine, but that doesn't work for our company, and I don't know if it necessarily works for the outdoor industry as well.\n\nCole Heilborn (16:57): You said something interesting. The people on your ambassador team are just regular people who have nine to five jobs. Where does that come from? You mentioned because you want it to be relatable and authentic. Is that your target audience for your marketing, or is that just a hope to kind of ground these people in the everyday average life so that all the rest of us average people can feel connected to them?", "token_estimate": 458, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "15:30", "end_timestamp": "16:57", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "8473212f-f661-4501-b5b0-095f21b34b99", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 9, "content": "Maddie Duffy (17:21): I think it's honestly probably a combination of the two. Obviously, we want everyone to be able to use our backpacks, whether you're an expert or someone who's just beginning, that's kind of like our marketing tactic behind it. We want people to have always wanted to go climbing, to have the ability to go climbing and learn from someone who has started from the bottom and really worked their way up to where they're at. I think I've had a few conversations with people who are into backcountry hunting and they're like, sometimes it's hard to relate to the people who are kind of a celebrity in hunting because they have all the access to all of this gear and to all of this land or this camera crew. But I want someone who's just an everyday person that I can relate to and who can answer my questions and it not feel like they're elite. They can be at my level and be like, yeah, I've been there and I've struggled with that too, and this is what I've done. This is what I've learned.\n\nCole Heilborn (18:30): Yeah. How do you find those people? It sounds like you want people who are really qualified experts at their thing, but they're also relatable. You wouldn't mind getting a cup of coffee or a beer with them and you wouldn't feel pressure of like, oh, I don't know if I can talk to this person so cool, or whatever. How do you begin to find those folks?", "token_estimate": 347, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "17:21", "end_timestamp": "18:30", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "36f9ebdb-1d6d-4dff-bc93-72ad52a860f3", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 10, "content": "Maddie Duffy (18:53): I think that they're all over, but I was saying a lot of the ambassadors that we have on our program right now, they've been there since the beginning. They've already had established relationships with a lot of the people at Mystery Ranch. And then I would say the ones that I have brought on since I started, again, they're known throughout the community. A lot of our sales managers will be like, you should talk to this person. And so what I do is I kind of interview them, and it's not a scary interview by all means because it's me. I don't think I'm a very scary person, but I have a conversation with them and I'm like, are these people easy to talk to? Just tell me about yourself. Tell me why you're in this market or you're in this industry. And I think when you can hear the passion and the excitement in their voice, that's where I'm like, okay, I want that person on my team.\n\nCole Heilborn (19:50): So then how do you get that person on your team? If you can share, is that compensated? Is that, what are expectations? Do you have a list of things that you require from them? Is it just like, Hey, we'll send you product and whatever you do with it is great. Where do you take it from there?\n\nMaddie Duffy (20:07): Yeah, so I mean, it's kind of a mix of things. So when we have that conversation just to kind of get to know each other and see if it's a good fit, the next kind of conversation that I'll have with them is What are your goals? What are your goals for 2021? What are your goals for 2022? And then make sure that their goals align with our goals and vice versa, because it has to be a mutual relationship because that's where you get that authentic side of your ambassador where it's like, this isn't forced. We're not forcing you to post this. And then from there, I kind of meet with our sales managers and then the rest of the marketing team and see where we might have gaps of maybe content that we need. And then I go back with the ambassador and I kind of just say, Hey, this is what we're looking for. Does it fit with all the hunts that you're doing this year or the climbs that you're doing this year?", "token_estimate": 540, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "18:53", "end_timestamp": "20:07", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "0fbae9dc-3d6e-4c71-8c4c-4a52f4c41b43", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 11, "content": "Cole Heilborn (21:02): So you've said that you'll make sure that your goals align. I guess, do you have specific goals for specific ambassadors that you're trying to match up with? And if so, could you share some of what that might look like?\n\nMaddie Duffy (21:16): Every ambassador I think is different because we are in different markets and each ambassador has their own different characteristics. Some people love to be on camera and love to do photo shoots or any films, and then we have some ambassadors that that's not really their thing. So it's just finding out the goals that align there. And that also kind of goes with the different characteristics of your ambassadors. We know that this person loves to be on camera. We know that this person just loves to talk about product or write a blog post for us. So yeah, I definitely think also depending on the market, each person has a different deliverable or a different goal for the year.\n\nCole Heilborn (21:58): And how important is leaning into your ambassador's strengths and taking advantage of the things that they're passionate about?\n\nMaddie Duffy (22:08): I think that's probably one of the most important things because like I was saying, we don't want a forced relationship. We want it to be very authentic, and if you're pushing something on someone that they don't want to do it or they don't feel comfortable, then it's not going to be a good outcome for either person. So just making sure that they're comfortable and asking realistic tasks of them, and I think, I don't know, that just helps build a better relationship with your ambassadors as well.\n\nCole Heilborn (22:37): Yeah. So I guess I'm curious then, so you've got your ambassadors, I imagine they're like you have 'em all on speed, Dolly, you guys hang out frequently, you go on adventures together, but then do you see, or do you work with I guess the influencer, maybe someone who isn't, I don't know. I guess we'll leave it there. Do you work outside of your ambassador program with other types of people?", "token_estimate": 511, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "21:02", "end_timestamp": "22:37", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "70f480d9-0e3b-4910-92a2-bb6f4e1996e1", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 12, "content": "Maddie Duffy (23:04): Yeah, we definitely do. It's something that I'm trying to establish a little bit more where we have an ambassador program and then an influencer program. And to me, the influencer program is someone who will write a blog for us in exchange for a backpack or write a review or help us with product feedback. That's always something that we look for. And I have people write in all the time, and we just kind of have a conversation about, okay, well, what would this look like if I did this huge epic hunt and I am normally a back skier, is that a story you would want to do? Can you provide us with backpacks? And so there is that different level of the influencer versus the ambassador. I think with the ambassador, I've just established a stronger relationship with them just because we do more consistent work with them. But that's not to say that we wouldn't work with any other influencer.\n\nCole Heilborn (24:08): Yeah. So I guess you've kind of described what the relationship with the ambassador looks like. What is the relationship and what are expectations that you guys consider when working with an influencer where maybe it's a one-time project or a much smaller ask? What does that look like?\n\nMaddie Duffy (24:25): Yeah, so we took on a platform called Meltwater that kind of helps us track the engagement that our ambassadors are doing. And then it also kind of helps us look for different influencers. And I guess what that really looks like is, again, it'll be a conversation of what project are you working on and where do you see us fitting in? Why do you want to work with Mystery Ranch? Another thing I think that's really important is when you're working with an influencer, it's like, we don't want this to be a forced push of our product. We still want that authentic vibe to it, so tell us why you chose Mystery Ranch. What do you know about us? Do you know anything about us? And then if not, we're like, okay, this is still a good opportunity. Let's educate them a little bit more on our product and see if it's still a good fit.", "token_estimate": 520, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "23:04", "end_timestamp": "24:25", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "eae04ee9-944b-4992-b63f-b886419a8738", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 13, "content": "Cole Heilborn (25:18): And are those people that you are finding and reaching out to, or do the most influencers come to you and then you get to know them?\n\nMaddie Duffy (25:27): It's a combination of both. Actually. Pre COVID, it was a little bit easier when we had trade shows and stuff, and you could actually have a face-to-face conversation with people. I definitely have had quite a few people come up to me at trade shows and we kind of have conversations and they tell me a little bit about the projects that they're working on. I've had people write into our Instagram, into our website, our different PR agencies, so they come from all over.\n\nCole Heilborn (25:58): Sure. Yeah. I guess for folks who are on Instagram and who are the type of people that reach out and want to share their adventures with brands from the brand side, is there anything that you would recommend an influencer or just someone mention or something that they could, if they're going to reach out to you, what should they say other than, Hey, can we have free product?\n\nMaddie Duffy (26:24): Yeah, I think it's always important to reach out and just give us a little idea of who you are. That will help me quite a bit. Maybe just talk about, this is what I've done in the past for other brands, or this is what I've built X, Y, and Z. Just give me a little bit of who you are and then also tell me why you want Mystery Ranch. Why do you want our product? How will it help you in your adventure? Or maybe you've loved Mystery Ranch for 20 years, but tell me why. Because we get a lot of that of, I love Mystery Ranch. Our products are great, and it's like try and make it stand out a little bit, I guess.\n\nCole Heilborn (27:05): Sure. What is Meltwater?\n\nMaddie Duffy (27:08): Meltwater is an influencer program, so for us, it measures all of our ambassadors, social channels. It just kind of helps me with the ROI to bring to my boss to help me set budgets for the year. And then it's also a tool where people can go and seek influencers at any different level. It gives them a rating based off of other companies that they've worked with before, their social reach, just kind of their reputation,", "token_estimate": 546, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "25:18", "end_timestamp": "27:08", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "24b5e82c-862c-4e90-b186-ecd20fa65dd5", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 14, "content": "Cole Heilborn (27:42): I guess. How do you set that up? Do you plug in your ambassador's channels, and then you can track analytics based on campaigns and posts and all that stuff.\n\nMaddie Duffy (27:53): So it's that. And then I also, I had to send them an email at the very beginning of getting that integrated and just having them kind of fill out their profile for Meltwater.\n\nCole Heilborn (28:05): Yeah. So what are you looking for on the analytical side? We've kind of covered the idea that it's not everything, but what do you look\n\nMaddie Duffy (28:12): For? One, just making sure that they're posting, so the actual content of it, and then just making sure that their posts, it is getting good engagement, it's reaching, it's resonating with their audience, and then that they're actually posting content too.\n\nCole Heilborn (28:31): Gotcha. And are there certain numbers that you're trying to hit when it comes to that information? Does that vary per person?\n\nMaddie Duffy (28:39): It varies per person, and I think it varies per market as well.\n\nCole Heilborn (28:45): Oh, okay. So you would expect to see a difference in engagement between outdoors and forest firefighting?\n\nMaddie Duffy (28:53): Oh, yeah. There's a huge difference for us. I mean, they both do equally well, but I think our fire community, because it's such a small niche of backpacks in the fire industry, that we do have a lot of wild land firefighters. We have a lot of military people, but what's cool is it all kind of overlaps because a wildland firefighter could be super into hunting or to backpacking all that, so all our consumers kind of dabble in each market.\n\nCole Heilborn (29:24): Gotcha. Yeah. Interesting. I never considered that, but I guess that makes total sense. What have you learned from being able to see those numbers? Have you guys observed anything that's kind of changed the way that you do things?", "token_estimate": 477, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "27:42", "end_timestamp": "29:24", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "82a10dc4-61e2-40fe-aa1f-3f465f4eb225", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 15, "content": "Maddie Duffy (29:43): We've only had Meltwater for a couple months, and so we haven't really done a deep dive into it. For me though, what I like is every month I kind of send a monthly update to our internal folks of this is what our ambassadors are up to, and I can kind of show them too through that platform, which has been huge for me because having Meltwater, I had to grab all of my analytics from Google Analytics and then actually going to our ambassador's page of taking screenshots and being like, this is what they're up to, but now it's all in one place, and so it's made my life so much easier.\n\nCole Heilborn (30:27): Yeah, I can only imagine. And I guess as you start to consider looking forwards, are you trying to continually to grow to your ambassador program? Do you try to keep it at a certain cap so it's manageable? Are you always trying to add people?\n\nMaddie Duffy (30:43): I mean, yes and no. I think it's important to keep your ambassador program at a certain cap because it will lose its credibility and more people that you continue to add to it. It's like, oh, well, everyone can be an ambassador, and that's not necessarily the case. I definitely think our influencer program is going to start to build out probably in 2022, and with our influencer program, I'm always willing to have a conversation with somebody, but yeah, they have to meet all the qualifications that we set and all the characteristics that we're looking for to be an ambassador at ranch.\n\nCole Heilborn (31:26): Sure. What do you see as, I guess two questions. What do you see as the biggest opportunities around ambassador programs and also the challenges around them?", "token_estimate": 418, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "29:43", "end_timestamp": "31:26", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "270716f7-2091-4b0b-afaf-64f75f6aece9", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 16, "content": "Maddie Duffy (31:37): I think one of the biggest challenges is just anything with social media or marketing in general. It's always expanding and it's always changing, and so it's keeping up with what's trending and what's not, what's resonating with your audience and what's not resonating with your audience? Is it bringing on more people? But if you bring on more people, it's like you need more management, you need, I don't know. And that's the other thing that's hard too, is all the content that you get from your ambassadors. Especially with us, we have 26 ambassadors right now, and so it's like managing 26 different content pieces that are coming in and making sure that it's getting distributed properly too, which that challenge is also a really good opportunity as well as we're running our social channels. I will never complain about getting too much content. It's hard to make sure that I'm putting it in the right spot and releasing it at the right time, but it's also a lot of fun and you learn a lot of things from it, and I think that's going to continue to be the biggest opportunity is you have these ambassadors that also have the time to learn different tools. (32:52): We have one ambassador who likes doing TikTok and reels, and that's not something that Mystery Ranch has dabbled in yet, but we have an ambassador to do that and help tell us a story on another social platform. I think that's the opportunity that Ambassador programs bring is just that broad reach of you might be reaching a new customer every day just because of your ambassadors.\n\nCole Heilborn (33:16): Yeah, that's an interesting point. How does, I feel like every year there's a new app or something that pops up, sometimes they stick around, sometimes they don't. How do you look at a new application and start to figure out, should we go down that? Should we not go down that? Do you kind of let your ambassadors test that out for you?", "token_estimate": 485, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "31:37", "end_timestamp": "33:16", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "1c872311-264a-4bfa-88ff-03a5d2462018", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 17, "content": "Maddie Duffy (33:39): Yeah, I mean, I guess it could be a little bit of both. I think for Mystery Ranch, you just have to make sure it aligns with your brand. For us, I think TikTok is great. I'm one of the millennials who actually watches quite a bit of TikTok embarrassingly, but I just don't think that right now, that's where Mystery Ranch is at, and we've had this conversation within the marketing team. That's not where our brand is at. I've also realized that Twitter isn't exactly where our brand is at either, but we still use it quite a bit. And I just use that platform differently than I use in Instagram or a Facebook with Instagram. I love having our ambassadors actually take over our Instagram for the day or two, and it just allows for our users to get to know them a little bit better and get to know this huge trip that they were on or their climbing expedition that they did, or skiing expedition that they did. But other than that, if our ambassadors want to start using TikTok, I think that's great. And again, it's just another avenue that kind of pushes people towards our product.\n\nCole Heilborn (34:54): How much do you look at your ambassador and see them as a way for the audience to get to know them and through them, mystery Ranch, how much of that is part of the equation?\n\nMaddie Duffy (35:06): I think it's a huge part. I mean, it's a good balance because with getting to know the person, you can also relate it to that product. I think it's almost more important for the people to get to know that person so they can instill trust and understand why Mystery Ranch would want to call them an ambassador. And yeah, the trust component is a huge part of it because the more they get to know this person, they'll start to trust their recommendations.\n\nCole Heilborn (35:35): How do you measure that level of trust or how much trust you have with your community?", "token_estimate": 473, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "33:39", "end_timestamp": "35:35", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "f53eebf9-d7e1-4913-94f6-95675a773b5b", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 18, "content": "Maddie Duffy (35:41): For me, I think when we first start bringing on ambassadors, I hate saying it, but we kind of put 'em on a probation period, and part of that is are they meeting up to their deliverables? So I think that's kind of the way that you as a company can build trust within these ambassadors. And if they're living up to their deliverables and they're posting on social media or they're being to the place that they're supposed to be at, I mean that in itself instills that trust.\n\nCole Heilborn (36:12): Yeah, interesting. How does that trust connect to this rise in micro influencers or nano influencers, I think is a new one. I've heard also, I've heard brands are now starting to go after folks who have less than a thousand or less than 10,000 followers intentionally.\n\nMaddie Duffy (36:29): I think that kind of goes back to what Mystery Ranch started their ambassador program with. It's like, maybe these companies are going after these people who have less than a hundred thousand followers because other people like you and me can look at them and be like, oh, they're just an everyday person and they're not just pushing a product to make money, they're pushing a product because they actually really like that product.\n\nCole Heilborn (37:00): Do you have a minimum follower count that you look for?\n\nMaddie Duffy (37:02): No. Our follower count. It honestly is all over the board. And I think that's kind of what I love about our ambassador program. It's not like we're just targeting these well-known athletes. Not to say that we wouldn't ever do that, but I don't know. I like that some of our ambassadors don't have 10,000 followers. They have under that, and they're still absolutely amazing at what they do.", "token_estimate": 435, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "35:41", "end_timestamp": "37:02", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "c9e87f7a-f0df-468b-9f26-f963db1fe2d4", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 19, "content": "Cole Heilborn (37:30): So I feel like sometimes maybe the politics of it get a little tricky because historically, I feel like in the outdoor space, athletes athlete deals were like, those were the people that we all looked up to. And now with social media, like the influencer and the ambassadors become a part of the equation as well. I've heard in the mountain bike space that some athlete riders or phenomenal riders ride for big brands, and I'm sure this is all over, but I'm just thinking of mountain bike right now. There's been challenges on the brand side because athletes or brands are working with athletes, they're also working with influencers like YouTubers, and they might not be the fastest on the bike, but they have that connection with their audience. And so brands look at that and they say, well, we obviously want to work with them so we can connect with this audience from the brand side. How do you manage that? Because on one hand you have athletes and they feel maybe a little jaded or, oh, we've put in all the time, we've worked really hard to get to where we are. We're at the top of our game, but here's these YouTube influencers who are these new people who maybe aren't the fastest, who just make videos for a living and we're losing brand deals. Have you seen that? I guess I'm just curious your thoughts on that topic as a whole.", "token_estimate": 341, "speakers": ["Cole Heilborn"], "start_timestamp": "37:30", "end_timestamp": "37:30", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "1eec41ab-e28e-4043-85e6-7afb40d91912", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 20, "content": "Maddie Duffy (38:57): I mean, I guess I haven't seen that on the Mystery Ranch side of things, but I could totally see that happening. But I also think that kind of goes back to setting up what you want your ambassador program to be and defining what makes an ambassador. Is it their social following? Is it that they're involved in their community? Is it their distribution? Figuring out why do you want that person to be an ambassador? Is it because they hit all the criteria that you're looking for? Or maybe they're really strong in three of 'em and not so much in the other. And I think I feel for those athletes that are getting frustrated, but at the same time it's kind of like, well, maybe this person is just a better fit for that brand. And it's not anything personal, it's just maybe the audience is resonating more with this person than it is with this person.\n\nCole Heilborn (39:53): Do you feel like we'll start to see more of that as more and more as the outdoor kind of become more accessible for everyone? And as we've seen through 2020, there's just been big push to get outside by the average person who maybe doesn't know who that athlete is, but they know who that person on YouTube is.\n\nMaddie Duffy (40:12): I mean, I hope so. For me, I think, again, it all goes back to that authentic feel with that person where I'm like, okay, I feel like this person truly wants other people to know about what they're doing or what they're using because they care. I mean, for me, if I see something on Instagram of someone being like, I really like this product and here's why I'm probably going to resonate with that more rather than a celebrity being like, I love L'Oreal. And it's like, okay. You also got paid so much money to say that.\n\nCole Heilborn (40:54): It's kind of an interesting segue, something that I don't know when it came out, but Instagram recently, maybe not recently in the last couple of years, put out there, shoppable content through the app. Is that something that you consider with your ambassadors, or do you think about that at all?", "token_estimate": 519, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "38:57", "end_timestamp": "40:54", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "388c690e-b3bc-4d31-979f-d398208aa7ba", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 21, "content": "Maddie Duffy (41:10): Yeah, so we actually just had this conversation earlier this week. Our company is just not there yet. We don't have discount codes that go with our ambassadors. Some of 'em do with some of our retailers, but it's not through Mystery Ranch. It's definitely an avenue. I think that Mystery Ranch should and explore. It could happen in the next year or so. I mean, who knows? But yeah, at this moment we don't do something like that, but I definitely think that that is beneficial for a lot of companies because you get to see that driver of where that traffic is coming from.\n\nCole Heilborn (41:51): Does that frustrate the user of Instagram though, when there's another place that they could buy a product? I mean, when I saw that rollout, I was like, come on guys, really? And now I can buy something through Instagram. There's plenty of other places I can go buy it. Why do I have to buy it through here?\n\nMaddie Duffy (42:11): I don't know. I mean, have you watched the social dilemma on Netflix?\n\nCole Heilborn (42:16): Yeah. Oh\n\nMaddie Duffy (42:17): Man, that gave me nightmares. I'm like, I'm part of the problem. I think that's, honestly, that's just the culture of the internet these days where it's like we just want that ease of use, and so wherever we can find an easier shortcut, I think that's just kind of how it's going to be from now on.\n\nCole Heilborn (42:40): I get that part of me wants to push back and say, no, let's not do it that way. But I mean, I guess I don't disagree with you morally. I feel conflicted about it all.\n\nMaddie Duffy (42:50): Yeah. Oh, definitely. It's marketing.\n\nCole Heilborn (42:54): Yeah, that's a whole nother topic. Actually, that's a good plug for an episode we did a few months ago with the social media manager, Mary Kate over at Goal Zero. We talked all about the social dilemma and the challenges that everyone on the brand side and the agency side who deals with social media. How do you do that and balance that with your own personal morals?\n\nMaddie Duffy (43:19): Oh gosh, it's a struggle.", "token_estimate": 518, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "41:10", "end_timestamp": "43:19", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "37c129f7-3977-4954-8b04-6b5c03a36188", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 22, "content": "Cole Heilborn (43:22): Yeah, I can only imagine. I think everyone has their own way to reconcile and deal with that. So if folks are interested to dive into that topic, go check out that episode. I think that was somewhere in the forties. I don't remember which episode number exactly.\n\nMaddie Duffy (43:38): I'll have to go listen to it. Something.\n\nCole Heilborn (43:40): It was fun.\n\nMaddie Duffy (43:41): I struggle with so much. I know I'll go through phases where I'll delete my personal Instagram for two months because I'm like, I've just had enough. I do this for a living. I look at it every single day, and then I have to switch over to my own personal side of things and I'm like, I can't do this.\n\nCole Heilborn (44:02): Yeah, I mean, everyone I think has their own level of tolerance. Some people just have more. Some people have less. I definitely have less of you on my Instagram. It's pretty bare. There's a reason this podcast Instagram is lacking. It could be way cooler, but it's not. And that's because I don't really enjoy Instagram. But anyways, what does excite me about Instagram and social media is the opportunity that I think you guys are working with and a lot of brands are working with, which is just telling these great stories through your ambassadors. As you look forwards, where do you hope your ambassador program will go? Are there things that you're hoping you'll be able to push into and try out for the next few years?", "token_estimate": 365, "speakers": ["Cole Heilborn", "Maddie Duffy"], "start_timestamp": "43:22", "end_timestamp": "44:02", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "aa046255-13da-44f0-9ee0-3ed72267ec5d", "episode_id": "926ad7a4-d22c-4225-845c-b8845aa6439e", "cms_item_id": "68225dfc7bb476527f8c4868", "chunk_index": 23, "content": "Maddie Duffy (44:50): Yeah, that's a good question. So for us, I really want to eventually evolve our social media to be broken out into certain markets, and I'm hoping with our ambassadors, we can do that as well. And then we can also do cross promotions of if we have a military focused Instagram, maybe someone from our outdoor can come guest star on it. I don't know. There's just so many different avenues, and I think that's, as much as social media can be a pain in the butt, it's also the best different way to tell different stories. There's so many different learning opportunities. There's so many different creative ways that you can get your product out there, your brand out there, and get your ambassadors involved in all of that.\n\nCole Heilborn (45:40): Well, Maddie, we're about out of time for today, but this has been a lot of fun. It's definitely been really educational, learning more about how you work with ambassadors, maybe how you don't work with ambassadors, I guess. Any lasting thoughts for our audience before we sign off?\n\nMaddie Duffy (45:54): Thank you. I think for me, the biggest thing that I can say about any ambassador program is just the relationship. Just really appreciate that relationship that you have with each of the ambassadors and nurture it. And I dunno, for me, I'm lucky because I can call all of our ambassadors, my friends. They're just such amazing people and it's always an honor to work with them and then an honor to see what they can produce from Mystery Ranch.\n\nCole Heilborn (46:21): If people want to follow along with you personally, if they want to follow along with the brand or any of your ambassadors, where can people go to connect?\n\nMaddie Duffy (46:29): You can go to our website and all of our social icons are at the bottom. And then also to our Instagram. I think each one of 'em follows us. So yeah, you can head on over there. There's a whole page about each one of our ambassadors as well.\n\nCole Heilborn (46:45): Well, Maddie, thanks again for your time today and I hope you have a great rest of your day.\n\nMaddie Duffy (46:49): Thank you. It was really nice chatting with you.\n\nCole Heilborn (46:52): See you.\n\nMaddie Duffy (46:52): Bye-bye.\n\nCole Heilborn (46:55): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 614, "speakers": ["Maddie Duffy", "Cole Heilborn"], "start_timestamp": "44:50", "end_timestamp": "46:55", "podcast_index": 64, "episode_name": "EP 64: Maddie Duffy | Ambassador, Athlete or Influencer? | Mystery Ranch", "slug": "ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "web_url": "https://www.portsidepro.com/podcast-feed/ep-64-maddie-duffy-ambassador-athlete-or-influencer-mystery-ranch", "guest_name": "Maddie Duffy", "guest_title": "Marketing Manager, Mystery Ranch", "categories": [], "short_description": "When it comes to building your team who are you working with? Why would you choose an athlete over an influencer? When is an influencer better suited than an ambassador? Why have an ambassador team in 2021?", "podcast_length": "44:86"}, {"id": "ff68a5fb-5eb9-4ae4-be5b-8518e6d2d056", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 0, "content": "Andy Bethune (00:00:05): The ultimate sin of marketing and branding, in my opinion, is trying to be everything for everyone because you end up being nothing. You end up being just like this watered down. Nobody really knows what you stand for.\n\nCole Heilborn (00:00:18): Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Sided Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo. Today I'm sitting down with Andy Bethune. He's the Director of Strategy over at Origin. They're a marketing and creative agency based in Whistler with offices in Montreal and Vermont. Andy, how are you?\n\nAndy Bethune (00:01:05): I'm good, Cole. Thanks for having me.\n\nCole Heilborn (00:01:07): Thank you for taking the time to chat today. How's your day going?\n\nAndy Bethune (00:01:11): It is going pretty good. It's one of those crazy days where it's like meetings and after meetings after meetings, but I'm excited to take a little respite from that and have a fun conversation with you about outdoor marketing.\n\nCole Heilborn (00:01:25): Yeah, and I mean, you guys, I feel like are one of the agencies, one of the premier agencies in the outdoor marketing world, so I really am excited to bring you guys onto the show and hopefully just kind of to start, give some background on Origin and a little bit more about your role as the director of strategy.", "token_estimate": 467, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "00:00:05", "end_timestamp": "00:01:25", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "18b9cdbb-3506-4e13-bce0-da007fbc1910", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 1, "content": "Andy Bethune (00:01:43): Absolutely. Yeah, so Origin, as you said, we're a marketing creative agency, focusing in the outdoor industry. So our business, I always tell people our business kind of revolves around two kind of pillars. A portion of the business revolves more around outdoor brands and manufacturers, and then the other half of the business sort of revolves more around the outdoor recreation and tourism industry. So I would say we kind of cut our teeth really in the world of ski resort marketing over the last 20 plus years. I probably know exactly how long one of the principles of our business, Danielle, Chris Manson, and MJ Lago started the business long before me. I've been there for 10 years now. But yeah, I would say we really cut our teeth on that ski resort marketing, and we're one of the earlier agencies to be working with some of the major resorts in that space doing content marketing and branded storytelling. (00:02:43): Whistler Blackcomb has been one of our major clients for a really long time and has been a client. We've been lucky to do a lot of really fun video work and storytelling work with, I think Cole, maybe you've seen some of that over the years. So we also work with destination marketing organizations, dmo, which is sort of the other side of that outdoor recreation and tourism part of our business. So those tend to be organizations in oftentimes mountain resort towns for us that are responsible for marketing the resort town as a destination as a whole. So yeah, between the ski resorts, the dmo, and then a lot of the outdoor brands that we work with, some of those recently have been Lululemon, LLL Bean. We work with Smart Wool over the years we've worked with North Face, Solomon a Number, rcx like a number of just those big outdoor brands on a variety of different projects. So yeah, really fun to work in that space. I'm personally an avid outdoorsman myself, and I always tell people I feel really lucky to be working on these kind of clients versus being in marketing for plastic fence or something like that. It makes life a little bit more exciting.", "token_estimate": 529, "speakers": ["Andy Bethune"], "start_timestamp": "00:01:43", "end_timestamp": "00:01:43", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "bf2ad1e7-ecf4-4732-89a4-498c98502748", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 2, "content": "Cole Heilborn (00:03:57): I've often wondered, are there people who live in Whistler who aren't outdoorsy? I feel like everyone who lives there does something outdoors. That's why you moved to Whistler, right?\n\nAndy Bethune (00:04:08): Yeah, I mean, Whistler is a crazy place. It, it's a funny place because compared to the rest of the world, a lot of people that are here who are the average Whistler rights would be sort of elite athletes. But when you live here and you're comparing yourself to the actual elite athletes that live here, it's a crazy place, but it has a really interesting double side to it. There's a lot of people, like my wife is a great example. She lives here and she likes to mountain bike and ski, but she's a very just average outdoor enthusiast and just loves the beauty of the place and the culture and the lifestyle and the community. A lot of people don't know that Whistler actually has a really active community. They just see it as a resort, but there's about 15,000 people that live here full time, and it's a great place to live. It's a great place for families. We're super lucky with all of the recreation infrastructure that we have here. But yeah, a really wide range of people, and that's helpful for us as an agency too, because one of the things that distinguishes us and makes us, or helps us have the expertise that we have is we attract a really great range of talent to work with our agency that comes from a wide variety of backgrounds and experience, but all kind of inherently understand the outdoor space and speak the language.\n\nCole Heilborn (00:05:30): Sure. So did you move, you said you've been with Origin for 10 years now. Did you move to Whistler to start working with Origin and what has your career path within the company looked like?", "token_estimate": 449, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:03:57", "end_timestamp": "00:05:30", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "f28ffc6b-9d97-41db-8f16-63ffea290e5b", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 3, "content": "Andy Bethune (00:05:39): I did. Yeah. I was actually, origin brought me up from, I was living and working in Bozeman, Montana, where I went to university at Montana State, and right out of university, went into the advertising business, started as an account manager in small agency in Bozeman, doing a little bit of work with a variety of clients, some in the outdoor space. I don't know if you know the company, mystery Ranch Backpacks. It's like a totally niche little,\n\nCole Heilborn (00:06:09): I think the episode one or two before yours, we did an interview with Mystery Ranch.\n\nAndy Bethune (00:06:15): Oh, no way. Awesome. So yeah, they were one of my clients back in the day, did some work with Adidas, fun outdoor kind of projects, but also was doing work for banks and hospitals and things that were less in my personal area focus. So yeah, I was offered the job at Origin, came up to Whistler in 2011 to start working at Origin, and I originally came on as an account manager, and just over the last decade, my personal area of interest and where I've developed my skillset has always been more on brand strategy, building brands, helping develop brands in a way that connects with audiences around the unique insights and things that make brands tick in the minds of consumers, really. (00:07:08): So it was a natural path for me to move outside of a more traditional account management role, grew into that strategy role. Also being Origin's a mid-size agency. So some big agencies have really distinguished account teams that are very separate from the strategy teams at Origin. One of the things that I think makes our account team really strong is a lot of our account team have a strategy, inclination or background. So you're kind of working with an account manager who really understands your brand and can contribute to your brand strategy. So yeah, we grew more of a strategy department in the agency over the last decade, and we now have a number of strategists, account strategists working with me as the director of strategy to service all of our different clients and provide strategic input on their accounts.", "token_estimate": 535, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "00:05:39", "end_timestamp": "00:06:15", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "7b8888ed-d2e9-4329-a27a-42f8935efd3a", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 4, "content": "Cole Heilborn (00:08:03): So give us, I know you could probably spend the entire episode talking about what exactly your job, what you do, but give us just a quick highlight so people have an idea of what does a director of strategy do at Origin?\n\nAndy Bethune (00:08:17): So the strategy role in an agency really revolves around being that person who can come into, into a client, listen to a client, explain some of the challenges that they're facing or the opportunities that they see, and really articulate those opportunities into a marketing opportunity. So a lot of times, one of the things we talk about in an agency is the difference between a client brief and a creative brief. A client will often come with something that they're trying to achieve or a problem that they see, but to get a creative team working on that problem, there's a whole step in the middle that involves uncovering insights and specific opportunities. So one of the things that we use as a strategy team is we write creative briefs where we take the input from the client, run it through a series of filters, do a bunch of background research, try and understand the target audience, really try and understand what it is about the brand and the strategy or positioning that that brand has, apply some cultural filters or filters about what's currently going on in society and look at competitors, bring that all together to create a strategic direction. (00:09:31): And that's sort of the role that myself and the other strategists on our team play is really being able to translate the client's ask into something that inspires a creative team to go away and come up with an interesting campaign idea or an interesting content idea or video series idea. It's interesting to look at it in the world of video because there are a number of production companies out there, and I know Cole, this is something that you are in the space and work a lot in, is trying to take things and understand, Hey, how does this video actually solve a business problem? And that's something that we do as strategists as well. It can be good to come up with an idea, this would be a cool video to go produce this and tell this story, but it's like, how do we actually connect that story or that piece of video content back to some kind of marketing objective? How do we understand how it's going to impact the customer's perception of us? How do we figure out how we're actually going to put that out into the market in a way that people are going to watch it or discover it? So understanding the distribution, all of that gets wrapped up into the realm of strategy.", "token_estimate": 658, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:08:03", "end_timestamp": "00:08:17", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "292e383c-2ef0-4a40-adba-c96112bb1dee", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 5, "content": "Cole Heilborn (00:10:39): Gotcha. Yeah, yeah, no, it's a never ending. I feel like process of trying to figure all of those pieces out. And sometimes they change too, once you get into it and you start finding pieces and then you realize like, oh, things are different than we thought they were. And those curve balls, I think you anticipate, but they're also, I dunno, sometimes they're surprising. I feel like\n\nAndy Bethune (00:11:04): They are, and it's not sometimes their strategy and creative, it's kind of like an art and science. It's this magical blend, and I'll be the first to admit that as a strategist, sometimes we come in and we are analytical thinkers and we come up with all these different ways of looking at a problem and bring something to a creative team. And the creative team just does something totally out of left field that's really exciting and interesting and you see it and you're like, oh my God, that's totally going to work. Throw the strategy out the window and just pursue the creative because it is an art. It's a blend of art and science, and sometimes the science can overcomplicate things and the art's just what needs to happen, but most times it's kind of finding that right sweet spot of the blend.", "token_estimate": 310, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:10:39", "end_timestamp": "00:11:04", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "7f7b4a43-477a-4702-8c2d-e93c00e34224", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 6, "content": "Cole Heilborn (00:11:50): So I'm really interested to learn more about, I guess this last year for origin because to kind of talk quickly, I feel like about the, I guess let's just call it the state of the outdoor industry, it's changed quite a bit in the last year and I think the trends that we're seeing now were already there. They were already in motion, but I think the last year of COVID has expedited that and compounded that effect. And I think everyone who's in the space probably realizes or has heard or listened to people talk about this new growing demographic of people who are entering the outdoor space who might not be considered that core group who maybe haven't been outside in a while, but they're just kind of picking it up. They're just interested and they're trying to learn and they're like, I want to ride a bike, but I haven't ridden a bike in a long time. How do I get started? I'm curious. I kind of want to dive into this, and we've talked about this change on the podcast before, but I really want to go deep into this and talk about some of the minutia to this change that we're seeing from your perspective from an agency, which isn't a perspective that we've had yet. So first just kind of set the stage for us. What are you seeing are the brands that you're working with, how are they reacting? What are they seeing? Let's start there.", "token_estimate": 343, "speakers": ["Cole Heilborn"], "start_timestamp": "00:11:50", "end_timestamp": "00:11:50", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "37ae8455-518e-41be-a513-96852fc1746c", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 7, "content": "Andy Bethune (00:13:14): Yeah, that's a great question. I think there's a number of variables at play. There's some variables that are kind of external factors, COVID being a big part of it, just the growth in the outdoor industry. There are some variables that are more intrinsic or internal factors to origin that we've seen over the last few years that have impacted this. But I would say one of the unique things that you asked, what has this kind of path look like for Origin? Over the last few years, we have seen growth in historically having worked with a number of more core outdoor brands and working on projects that really celebrate the more traditional core outdoor consumer. And a lot of those things look like in the content realm. It's the outdoor industry is such a great place to work in content because we've been doing content marketing since the onset, I think of the old skateboard and snowboard movies that I grew up watching in the nineties, and that was content marketing. (00:14:24): It was not sophisticated content marketing, but it was a bunch of snowboard clips on the back of a bunch of snowboard brand logos. And that was how you, I grew up drawing forum and special blended Foursquare logos on my notebook and school and things like that. Those were the brands that brought me the content that I grew up watching. So as an agency that historically had a lot of work with those core outdoor brands, we were doing that kind of content, more ski snowboard, outdoor mountain bike, outdoor content. What we've seen is that as the brands that we've worked with have grown into bigger brands like Lll Bean and Lululemon as two examples, the target audience for those brands just it really broadens out and all of a sudden you're not just selling $800 Gore-Tex jackets or a thousand dollars free ride skis to a core ski consumer, you're now selling $80 fleece jackets or puffy vests, or you're selling yoga pants or kind of casual outdoor leisure wear to a really broad range of consumers who don't sit around watching core outdoor content. (00:15:49): They're not on the TGR website, they're not following these core endemic media spaces. And it's an interesting marketing challenge because I don't want to trivialize the core outdoor marketing. I mean, there's so much really good stuff out there, but it can be easier to figure out how to reach that audience and what kind of content, what kind of storytelling, what kind of messaging is really going to resonate with them because we just intrinsically understand those people and niche audiences tend to be easier to reach in these niche distribution channels and things like that when you're trying to reach a broader audience that their life is just full of stuff and the outdoors to them. They don't define themselves by their outdoor participation like some of us do in more of the core outdoor space. They're multifaceted individuals, they're moms and dads, they're taking their kids to soccer. (00:16:45): They have careers that don't revolve around the outdoor. They got so much going on in their lives. So trying to determine how you reach those customers with marketing is a really interesting challenge as we've kind of expanded the brands that we work with. I think the other thing that we're seeing is we're seeing so much more that's more of an intrinsic variable for Origin, the brands that we work with and how that's changing. I think at the more external level or industry-wide level, we're just seeing a lot more crossover between casual wear, outdoor wear lifestyle brands. Just before this, I was just watching a video about some of the things that are happening in the fashion world with Arc TerraX. I don't know if you're familiar with any of this stuff that's going on there?", "token_estimate": 945, "speakers": ["Andy Bethune"], "start_timestamp": "00:13:14", "end_timestamp": "00:13:14", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "ad948318-fb01-417e-a0c0-95e6455ef714", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 8, "content": "Cole Heilborn (00:17:36): No, I don't think so.\n\nAndy Bethune (00:17:38): Oh, it's really interesting for people to take a look at the Arc TerraX Gore-Tex outerwear and puffy jackets and things like that have become this staple or hot topic in streetwear and fashion. And you've got fashion designers hacking up Gore-Tex shells and sewing them onto Tutu. And I'm not a fashion person, so I'm probably not describing this well, but doing these crazy mashups of hardcore mountaineering wear with really fashion forward things and seeing this on catwalks in Paris and stuff like that. And places like Hype Beast covering all of this are very different spaces, and it's been really interesting to follow how Arc TerraX is navigating that it. (00:18:27): But yeah, it's unique to see this crossover in the industries and more people who are exploring and breaking out into the outdoors in these really casual ways. I work with a client right now and we developed a target audience for them. We talk about them as these urban outdoor curious millennials that maybe a couple of years ago spent most of their free time going to the bar, going to music festivals, but now maybe this memorial weekend they're going to go camping at a park state park with a couple other buddies, and it might be the first time that they've ever been camping or they bought hybrid mountain bikes this year to explore some of the gravel trails around their neighborhoods. And for that audience, the distinction between, okay, so I need some shorts and some tennis shoes or shoes or footwear and maybe some active wear tops and things like that to go ride my hybrid mountain bike on these trails around my neighborhood to distinguish between Nike or Reebok or Adidas versus the North Face or smart wool or something like that. (00:19:39): They don't have the distinction that a core outdoor customer does who would probably wouldn't go skiing or mountain biking in Nike. So they're navigating this fluid brand landscape of outdoor brands and fashion brands and leisure brands and sport brands. And the same crossover is happening in that they're in the same way that they're kind of getting into more of these outdoor brands for some of the activities that they're doing. They're using outdoor brands more in a lifestyle way. So the North Face is a classic example of that where we see that for a long time. We've seen the North Face present in a lot of lifestyle use. So yeah, just a really interesting mashup of industries that historically were a little bit more segregated.", "token_estimate": 637, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:17:36", "end_timestamp": "00:17:38", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "245ced91-ba47-4e8c-bc75-4fbdc2a6535f", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 9, "content": "Cole Heilborn (00:20:30): In our intro call, you had said something that I jotted down this idea that historically marketing to the core is easier. Maybe it's just because we've been doing it for longer, but we understand their motivations and their needs and but when it comes to this new wave of people, we don't really understand them as well. We can't label their motivations or their needs as well as we can label the core enthusiast. Can you kind of speak to that and how are you trying to figure out who are these people and what do they want? What problem are we solving?", "token_estimate": 145, "speakers": ["Cole Heilborn"], "start_timestamp": "00:20:30", "end_timestamp": "00:20:30", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "f63d5fb7-4708-4d10-a4f4-f2704c7517db", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 10, "content": "Andy Bethune (00:21:09): Yeah, that's a great question. So that is, earlier you asked what does a strategist do? I mean that's a huge part, particularly in brand strategy of understanding the target audience and what motivates 'em. I think part of the reason it sounds trivializing to say outdoor marketing to the core is easy. It's not. There's so much complexity and there's so many great marketers at all these brands that are doing incredible work. So we don't mean this to trivialize that in any way, but I think that what we've seen historically is that the insights that drive outdoor marketing about the audience, they tend to be really focused on these are audiences that are motivated by accomplishment, they're motivated by celebration of the accomplishment of the sport or the cutting edge of the sport. So core ski and snowboard is about going bigger and faster and climbing bigger mountains, skiing bigger lines, hucking, bigger cliffs, and we know that the core audience is really motivated by that accomplishment or they're interested by that. They aspire towards that. So that's the type of content that they like to see. (00:22:25): We also know that one of the things that the outdoor industry has been guilty of for a long time is just being really focused on product. I hope I don't offend anyone in the mountain bike industry when I throw them under the bus a little bit here, but the mountain bike industry is such a classic example of an industry that is run by engineers and so much of the marketing that occurs in that industry is around millimeter measurements of components and things like that. That's just when you're a bike nerd, I think you are like I am, you kind of follow that stuff and you get hooked into it of like, oh yeah, I got to get these bars are 20 mil wider or whatever it may be. But when you're not, that stuff's like it's just Greek. It doesn't make any sense. So yeah, one of the things that we look at when we reach out to these broader audience segments is what is it that motivates them If they're not motivated by accomplishment or perhaps it's not that they're not even, they're not motivated, they're intimidated. (00:23:26): These brands that position themselves, everything's about being gnarly or bigger or more hardcore, that's intimidating. They feel like a poser. If they wear those brands, they're like, I can't wear that brand. I'm not that hardcore. They're not intrigued by the technical, how many is this a three L Gore tech? They don't even know the difference between three L and two L, right? A lot of people don't. That kind of storytelling doesn't resonate. So one of the things that we've really looked at is just just trying to understand these different audiences and what does resonate with 'em. We find in a lot of cases that it's more values oriented, so what does the outdoors mean to them? And for different brands it's different things because every brand has their own values and the sweet spot is aligning your brand positioning with a target audience that shares those values or that appreciates what you represent as a brand. Patagonia is an interesting brand in that for a long time conservation and environmentalism has been at the heart of that brand and it's been interesting to see that brand grow and then figure out how to refocus itself on that over the years. Could tell you some funny stories about that.", "token_estimate": 850, "speakers": ["Andy Bethune"], "start_timestamp": "00:21:09", "end_timestamp": "00:21:09", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "186bf605-9280-4056-ae9e-1a4aa1dd0132", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 11, "content": "Cole Heilborn (00:24:43): I mean, talk about an urban brand.\n\nAndy Bethune (00:24:45): Yeah, totally. Well, I worked with a strategist once who had worked on some Patagonia projects and something interesting she told me was they had a specific strategy that they developed the KPI that they attached with the campaign was the reduction, the uses of the hashtag patagucci and Fredonia f (00:25:08): Frat. They were marketing to try and refocus on their audience and get shed some of that less desirable audience or brand perceptions audience that they had built. But a little tangent there. But yeah, we did some work with Ella Bean over the last couple of years, which has been really fun and interesting and they came to us to help reapply some focus on their hunting and fishing heritage. So I don't know how many of the listeners are familiar with LL Bean, fairly well-known brand in the states. They actually were founded in the 18 hundreds by this guy, Leon, Leonard Bean, I think his name was is where LL Bean comes from. And he was a hunter living in the backwood of Maine building hunting boots for moose hunting out in Maine. And so they came to us looking to, they have a big undertaking of reconnecting their brand to its outdoor heritage over the last few years. (00:26:10): And one of the things that we started working with them on was celebrating the hunting and fishing heritage of that brand. But when we looked at they trying to reach, it wasn't hardcore archery hunters or fly fishermen and things like that, it was more of the casual outdoor enthusia that sort of aspires to live this outdoor lifestyle. Most of us, I'm sure grew up putting a worm on a hook and sitting around the lake with our friends or parents or whatever it is, fishing. And so we took a look at, okay, how do we create content and messaging and storytelling that celebrates phish and celebrates the brand's heritage in that space without going down the road of creating some hardcore story about this fly fishing guide in New Zealand that does takes people on these epic adventures to catch 30 inch brown trout and stuff like that. (00:27:03): And what we really found was this interesting angle of celebrating the connection that occurs through fishing and the mentorship hunting's the same. These activities largely get handed down through mentorships, and that's a really interesting angle that we were able to find some cool stories. So we found a guy in Florida has a company called Take a Kid Fishing or an organization called Take a Kid Fishing that works with underprivileged kids and foster children and things like that to just introduce them to fishing and the joy of the outdoors. And we told that story and it was a beautiful piece of content. We worked with a couple out of Bozeman where I'm from who have a fishing lodge there, and their entire relationship revolves around fishing. They own a fishing lodge as a couple together there. But the story we told was really about this woman, Laura, her progression as a fisherman fisherwoman through the mentorship and relationship that she has with her husband Jake, and how that bond that they formed that's largely around fishing, is a huge part of their life. And those stories about mentorship or relationships or love or teaching kids new things, those resonate with people who don't care about hardcore mountaineering or less worried about the size of the fish and they're more just interested in the experience and what it provides. So (00:28:38): Looking at different angles, looking at different different values that those people have.", "token_estimate": 900, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:24:43", "end_timestamp": "00:24:45", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "d8a53656-6ac6-4cd0-9e25-5721967d949e", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 12, "content": "Cole Heilborn (00:28:45): So yeah, your lb, an example is really interesting. Maybe we can dissect that a little bit. I guess what I'm confused by or what I want to understand is how much should a brand plant its flag and then let that community come to them versus looking at the consumer and saying, oh, let's try to fit in with these people because LL bean is an interesting example. I feel like where they have that heritage, they know who they were when they started, they know who they are, but they're also changing maybe a little bit of their focus away from that core into that more like the campaign reflected that, I don't know, more casual relationship experience based experience rather than the size of the fish. Does that make sense? Does that question make", "token_estimate": 193, "speakers": ["Cole Heilborn"], "start_timestamp": "00:28:45", "end_timestamp": "00:28:45", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "34186a94-6955-4253-8237-697094f0d8f7", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 13, "content": "Andy Bethune (00:29:40): Sense? Yeah, I understand what you're getting at of maybe what you're asking is do you build the brand to the target audience that you're seeking or do you let the audience come to you that is going to resonate best with your brand? I mean, it is a really interesting question and it's different for different brands. If I'm building, I'm currently building an outdoor brand from scratch with a client where there's so many variables, but the client has an idea of what they had an idea of the type of product that they could build. They had an idea of the type of distribution and wholesale relationships that they could achieve, and they came to us saying, look, we feel like this is the type of product that we have. This is where we want to sell it. This is kind what we have in mind. They had this idea of democratizing outdoor apparel and making it really accessible. (00:30:45): And they came to us and said a brand around this. And one of the big things that we did was we did a lot of research on what audience segments are out there. And for example, the Outdoor Industry Association a few years ago did something called Consumer View Consumer, VUEI think it is, where they created all these, they did a bunch of research and created these audience segments. And if you were trying to build a outdoor brand from scratch, one of the best things you can do is go look at this segmentation model and trying to decide, Hey, who am I trying to build this brand for? Because\n\nCole Heilborn (00:31:17): Where can people find that, sorry.", "token_estimate": 392, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "00:29:40", "end_timestamp": "00:31:17", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "389f6eca-fd44-4722-8429-1089875c1819", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 14, "content": "Andy Bethune (00:31:19): You can find it on the Outdoor Industry Association website I believe. Or if you just Google Consumer View, and I'm pretty sure it's spelled VUE, (00:31:28): You'll probably be able to find that segmentation model and it's a little older and hopefully they'll update it soon to maybe accommodate some of these new trends we're seeing in outdoor demographics. But that segmentation ranges from on one end of the spectrum, the hardcore elite athlete all the way to a 60-year-old woman who spends most of her time gardening. I don't want to play in the stereotypes at all, but there's part of segmentation is to somewhat you stereotype a little bit to segment audiences. So yeah, you can really cover a wide range and the ultimate sin of marketing and branding in my opinion, is trying to be everything for everyone because you end up being nothing. You end up being just this watered down. Nobody really knows what you stand for. So definitely focusing in on who your audience is and how do you build a brand that resonates with those people is important. But there's an authenticity factor that is as critical as this idea of not being everything to everyone and consumers are smart man. They can sniff out a brand that's trying to just build something to pander to this perception that they have of that audience pretty quickly. And they want authenticity. They want to know that that brand stands for something. And that's where we see a lot of focus around brand purpose. (00:33:00): And Patagonia is the poster child of a purpose-driven brand, but we are seeing it more and more that brands are really trying to understand like, Hey, what do we stand for outside of profit? And you asked the question about LL bean, what's sort motivating them to reach this broader audience? I think there's been a lot of introspective work at LLB over the last few years there at a leadership level, at a board level where they have really been reconciling where the direction that their brand has gone over the last a hundred years. For a while it was a little bit of that everything to everyone catalog brand. Most of us know it as the catalog brand that was on maybe your parents' counter or something like that. Everything from slippers to khakis and Home Goods and things like that. They realized that that was a model that used to work really well. But as things have changed and people are looking for specific brands to fill specific purposes in their life, they want those brands to have authenticity in a certain space. And that's where LL Bean is really revisiting their purpose as an outdoor brand and are putting this focus on helping people celebrate the shared joy of the outdoors and understand the rejuvenative power of the outdoors. These are things that are kind of being talked about at the level of purpose (00:34:30): And that helps them focus in on the type of storytelling that they want to do and focus in on the type of audience that really resonates with that as well. Right. So it's a mix. I dunno if that answers your question. It's not a one or the other answer. I think it's kind of finding that balance between making sure there is a customer, but also making sure you're true to something that your organization stands for and believes in.", "token_estimate": 822, "speakers": ["Andy Bethune"], "start_timestamp": "00:31:19", "end_timestamp": "00:31:19", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "56a3cc45-b960-441e-a62e-77fd03caf901", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 15, "content": "Cole Heilborn (00:34:57): Okay. Yeah. I guess a couple clarifying questions just to go a little deeper and not, I guess we'll keep using LLB as an example. We're not trying to pick on LLBI suppose. Yeah. You said to you the biggest sin of marketing is when you try to become everything or something to everyone or everything to everyone.\n\nAndy Bethune (00:35:18): Yeah, everything to everyone.\n\nCole Heilborn (00:35:20): So if brands now are seeing these new demographics entering the space and they're saying, okay, if we want to, I don't know, survive or if we want to be inclusive, we need to still talk to our core, but still invite these new people to join us. When do you go too far? When do you become everything to everyone? Where's that line in the sand in your mind? If brands are opening themselves up to maybe something that historically hasn't been their focus,", "token_estimate": 219, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:34:57", "end_timestamp": "00:35:20", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "e16f47d0-d4f6-412d-b2ab-98722ea5f173", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 16, "content": "Andy Bethune (00:35:59): That is the million dollar question and it is what most in the lifecycle of a brand, it's what a lot of brands struggle with. So perhaps an example of a lifecycle of a brand is you have a small brand that starts a niche little brand like Mystery Ranch, as we were talking about earlier, is kind of a cool example of that for people that aren't familiar with them, this guy, Dana Gleason started this brand after he sold a hardcore backpack company to K two, and they make probably the most high quality made in Montana. Hand sew backpacks for military use, firefighters, wildland firefighters, hardcore back country hunters and anglers and recreation like skiing, mountaineering, their product is super niche. The packs are like 700 bucks. Most people, your average hiker isn't going to buy a $700 pack. So you kind of start there and you grow into that niche. (00:37:01): And then a lot of times what happens is a company like that is really successful in that niche, maybe gets acquired, gets investors, whatever it may be. And regardless of what the pressures are, a lot of times there are external pressures to grow the business. And when you look at how do you grow that business, one of the most obvious things is to try and reach new audience segments with new products. And you end up, maybe now you don't have only $700 backpacks, you have the $200 backpack version. It's like, but now you've watered down that reputation you have for making the hardcore $700 backpack that's used by Navy Seals and wildland firefighters. Now all of a sudden you've got a bunch of people with a $200 backpack and you've watered down that brand. So a lot of times what happens is there's a bell curve. You see these brands, they grow, they grow, they grow, they get to this point where the brand is as relevant as it can be and they've optimized with the right audience, and now they're trying to figure out how to grow bigger and they plateau and some brands tank, they ruin their brand. (00:38:08): The question of how far is too far is a super subjective question. We could have conversation, we could sit here and pick apart all kinds of brands. We could look at Art Teex, we could look at the North Face, we could look at a number of these brands. I think Art TerraX is a really great example of brand that's currently grappling with this and is doing a good job of navigating it. But if you go and look at the marketing and messaging that's coming out from them, you'll see it spans a broad range. We did a project with those guys last year maybe where we created a piece of content about the spearhead traverse, which is a backcountry ski traverse up here in Whistler that there's been a new initiative to build some backcountry huts. And we told a whole story around the process of building these huts on that traverse and how TerraX has been involved in the customer for that as a hardcore ski touring customer. (00:38:58): But you'll see that they're also doing content that resonates with a broader audience. They're working with influencers that are perhaps more in the lifestyle space or have a broader reach. And I think what they're looking at is just how do you expand outside of just that core marketing in a way where it still connects to something that defines your brand. To me, for Arc Alteryx, that's always going to be this sort of technical factor. And even as you look at how these, I was saying fashion brands are kind of adapting or taking Art Alteryx product, it seems to me what these fashion designers are really latching onto about art Alteryx are these hardcore technical fabrics and these interesting patterns and things like that. So again, really understanding what it is that makes you unique and figuring out how can you extend that in ways without going so far away from it that you're no longer who you are. The North Face has taken a lot of critique this year over their partnership with Gucci. I dunno if you've seen that at all. That's a really interesting one.", "token_estimate": 1005, "speakers": ["Andy Bethune"], "start_timestamp": "00:35:59", "end_timestamp": "00:35:59", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "44825a23-0380-4fbd-a429-8b2edb47bc48", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 17, "content": "Cole Heilborn (00:40:07): I'd love to do an episode on that because I think that's such an interesting conversation.\n\nAndy Bethune (00:40:13): Man, it would be fascinating. It's a super interesting partnership and in my mind I would say that's one where it's like I just can't see the connection to the, I can't see the connection to the heart of the brand in that, but North Face is also a brand that had, when we talk about the lifecycle of brands, they've been dealing with this challenge for about as long as any brand can. They were arguably the Pinnacle outdoor brand that became mainstream. So they've been grappling with that for a long time.\n\nCole Heilborn (00:40:45): I don't want to make it sound like they're just kind of abandoning their core and opening their arms to anyone now, but in some way it kind of seems like they could be. Is there risk of losing that core group of people who made them who they are?", "token_estimate": 231, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:40:07", "end_timestamp": "00:40:45", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "7a80eb78-1907-4c12-ba3c-e78d98c8b9c0", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 18, "content": "Andy Bethune (00:41:01): There absolutely is that risk. And I think when we bring it back to North Face, well first of all that North Face Gucci collab is a very small thing and you could argue that all good or all PR is good PR that it brought a lot of attention to that brand. One of the things that North Face does is while they're off doing Gucci Colabs and these more fashion and street wear projects that they're working on, they're still doing things like their Future Light product launch, which is, I think, I can't remember who the Pinnacle athletes were that they were working with guys like Jimmy Chin and stuff like that, where that future light launch was largely focused on the core athlete and the relevance of that product and that brand in the core space. So they can say, Hey, we're doing Gucci stuff over here and we're doing $600 retro purple North face jackets for urban millennials over here and things like that. (00:42:11): But we're still doing innovative product, innovative technology. We're still supporting these expeditions and things like that. We're still working with athletes who are telling us this is the best product they've ever used, all of these kinds of things. So now maybe that's kind of starting to explore this everything to everyone space that I was just talking about. And you could argue that that's one of the things that North Face is maybe grappling with, but they haven't let go of what makes them core. Yeah, I think brands that really let that go, they can quickly, one brand I'm going to pick on here, and I hope that nobody is offended, but I think Eddie Bauer is an interesting example of a brand that has really struggled with that. Most people don't really know what that brand stands for, but if you look at the history and heritage of that brand, it it's a lot like LL Bean. (00:43:06): I mean it started as a core outdoor brand. They have their first Ascent product line, but not a lot of people really understand the relevance of that brand in the core outdoor space. The fact that it's associated with Eddie Bower is a little bit of a disconnect. So that's a brand that I think is grappling with that and trying to figure it out. There's so many variables in that. It's like their distribution, their margins, all kinds of those kinds things that it's some people, maybe people probably now see that as a mall brand, like a casual wear mall brand, but you can go and buy a $500 Gore-Tex shell at some mall in Seattle and Eddie Bowers shopping a mall in Seattle, and it's like it's high quality product, but that brand is just so disconnected from that space now that most people don't make that association anymore.", "token_estimate": 670, "speakers": ["Andy Bethune"], "start_timestamp": "00:41:01", "end_timestamp": "00:41:01", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "6d73a4cd-9b66-458a-85fa-2bd8af768d14", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 19, "content": "Cole Heilborn (00:43:58): This is kind of a tangent, but it's something interesting. I was reading the memoirs of an autobiography, or I dunno, a book written by Jim Whitaker about their ascent on Everest and in it they were talking about their sponsors and one of their sponsors was JamSport. They made their backpacks,\n\nAndy Bethune (00:44:20): Which\n\nCole Heilborn (00:44:20): I just think is so wild with what I think of them now. So talk about a brand, I don't even know a brand shift, like a change when I read it just kind of blew me out of the water. I was like, what they, why would anyone use one of those?\n\nAndy Bethune (00:44:36): I know that's a great brand example. I think years ago, I think I actually read a biography by the founder of jansport and he talked about some of that, which is kind of interesting. But on that same realm, the kind's interesting because the kind to me for a long time has been a pretty hardcore surf mountain bike ski brand. But if you look at the direction that they're taking that brand right now, and I would be doing the same thing if I was in the marketing department there. It's a lot around kind of the way that their backpacks, since a lot of their product is used in streetwear and back to school and gen, I don't know what the younger generation beneath Gen Z is, but really quite a youthful generation\n\nCole Heilborn (00:45:24): To have a kind backpack in high school. For me, that was the thing. You were cool if you had one of those.\n\nAndy Bethune (00:45:29): Yeah, totally. Yeah, absolutely. If you look at some of their marketing now, it's really different. Some of it's really focused on more to Kind is never seemed like an urban brand at all. To me. It was always like, it's Hawaii, it's Hood River, mountain biking and surfing and skiing, and they're really focusing, there was a huge market opportunity to sell urban backpacks, urban transit backpacks and things like that. And they're looking at how do you explore that space while still maintaining a connection to your core outdoor heritage. And it's just an interesting challenge.", "token_estimate": 525, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:43:58", "end_timestamp": "00:45:29", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "540cbc6d-04e3-4632-9643-d693289989d6", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 20, "content": "Cole Heilborn (00:46:02): And to back that North Face example where you're talking about, was it the ultralight or what was it that you were\n\nAndy Bethune (00:46:08): Future Light? Future\n\nCole Heilborn (00:46:09): Light\n\nAndy Bethune (00:46:10): Is their new fabric that they kind of had a huge launch around. Yeah.\n\nCole Heilborn (00:46:13): Okay, so they've got this future light campaign going on with high profile athletes the same time they have their CoLab going on with Gucci, two very different things, but I guess how do those connect? We were talking about that underlying message that allows a brand to expand into those different categories or those different focuses, but what is it about that that arguably works? Maybe it doesn't work.\n\nAndy Bethune (00:46:43): I know maybe know, I don't know the Gucci one, but Well, look, there was a piece of content that they released for that Gucci CoLab that, I don't know if you saw it or if the listeners have seen it, but it has this funky seventies retro vibe. If you seen that piece.\n\nCole Heilborn (00:47:01): I think it was the aspect ratio was four by three I think.", "token_estimate": 283, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:46:02", "end_timestamp": "00:47:01", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "e8e3a375-3e86-4880-8b41-5d7909e3afd2", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 21, "content": "Andy Bethune (00:47:04): Yeah, it was shuttle funky and it's, there's Afros and Rose tinted aviator glasses and stuff, and it's very, so I think there's a big, like I said, I'm the least qualified person to be talking about the fashion space, but from what I perceive is there's a big movement back to bringing some of those styles and fashions from the seventies and the back. And I think the North face a few things. North Face has, they have a definitive retro vibe from an era. So they're actually, north Face does a lot of retro product and it's pretty successful from what I understand. And when you think about the outdoors in the nineties, the eighties and the nineties, you think about those classic North face silhouettes and color blocking and there's purple and black and yellow and black jackets and parkas and things. That's a little different than the seventies vibe that we were seeing in the Gucci thing. But first of all, that brand has some retro cred. (00:48:12): I think that though, when you look at the way that the Gucci CoLab was put together and the content that was created around it, it wasn't like North Face product being used in urban experiences. So it's not like guys sitting around in smoking cigars and cigar lounges in North Face stuff. That's a random example, but it was this group of young 20 somethings out in the mountains camping or doing what appeared to be some kind of camp. I don't know, they were wearing some strange stuff for camping, but it was still connected to this kind of idealistic, maybe seventies era image that we had this sound of music kind of vibe going on as well of wildflowers and these alpine meadows. And it still had some connection to the outdoors. And like I said earlier, the fashion space is really interested in the outdoors right now, which is why I ran Gucci probably deems it appropriate to explore a North Face CoLab, and that's where there's some crossover there. Now, look, I'm not sitting here saying that North Face Gucci CoLab is true to the DNA of the North Face brand. I'm not part of those. I don't know what's going on with the decision making there.\n\nSpeaker 3 (00:49:39): Sure.", "token_estimate": 542, "speakers": ["Andy Bethune", "Speaker 3"], "start_timestamp": "00:47:04", "end_timestamp": "00:49:39", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "f876c026-3c57-44f5-9808-3fe957a91282", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 22, "content": "Andy Bethune (00:49:40): But you can see how it may be connected. I think also a brand like North Face is big enough that they can, it's established enough that they can have these niche things going on, right?\n\nSpeaker 3 (00:49:50): Yeah.\n\nAndy Bethune (00:49:51): Carhartt's another interesting brand where Carhartt, I saw this funny meme where it's like, I don't know if your Carhartt beanie is telling me that you're a welder, a college student or a New York City fashion person or something like that. It's a confusing brand that three completely different types of people can wear it and feel really connected to that brand. But yeah, it's a big enough established enough brand that people can kind of take it and use it in the way that they want to use it. For a small brand to try and do that and capitalize on that to me is suicide. You don't have that cred you that authenticity yet for people to be able to take your brand and start applying it in their own unique ways.\n\nCole Heilborn (00:50:40): That Carhartt example is really interesting. There's three very different segments to that audience, but they all work. I mean, I feel like they work. (00:50:54): Yeah, I'd be curious to learn more about how that team, how they see all those connecting At some point, do you just let things run and you're like, you know what this is people are doing with our stuff. This is how pop culture or music has influenced and changed our brand. We're just going to let it happen. How much of it do you, so okay, so maybe here's a question. How much does a brand try to control that? How much do they just let it happen? How much do they try to influence it? That Patagonia example where they were trying to cut down on that number of hashtags, I guess what's your thoughts or if a brand comes to you and says, we're trying to do this, how do you navigate that?", "token_estimate": 466, "speakers": ["Andy Bethune", "Speaker 3", "Cole Heilborn"], "start_timestamp": "00:49:40", "end_timestamp": "00:50:40", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "77b476df-e592-4afd-8501-087184815cb6", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 23, "content": "Andy Bethune (00:51:33): Well, I think there's lots of different things you can do. Carhartt has, I don't know if you're familiar with it, but they have a line called Work in Progress, which is they kind of created an offshoot or sub-brand under Carhartt, and there's a whole realm of brand strategy that's called brand architecture, and it's how you can have a Toyota can own Scion, Toyota, Lexus and have different brands market to different price points and different target audiences and things like that. So Carhartt sort of explored something like that with Work in Progress. It's more of their fashion oriented, it's weird stuff. It's like $300 from what I can tell. It looks like a sort of Carhartt jacket, but it's more fashion oriented and it costs 300 bucks, but they've created that kind of arm. But what's interesting is I think a lot of people, they're still just latched onto the original Carhartt product and brand and it's like those orange beanies with the Carhartt label or the Tan beanies seem to be the popular thing. I think what's interesting about Carhartt is regardless of all that stuff that's going on, they've really stayed true to their core message. And if you look at their marketing, you look at interviews with their VP of marketing, things like that, they still are really focused on celebrating what makes that brand tick, which is this commitment to the hardworking American values that this country was built on, all that kind of stuff. And it's a super authentic and super resonant heritage story and people eat it up. (00:53:02): I think that's what seems like what they are doing is letting people pick up their brand and use it in all kinds of ways that they need to and letting that brand live in these niche circles without trying to jump on and take advantage of that and be like, oh, we're really missing this opportunity to grow our brand in fashion. They did it with work in progress, I guess, but they're not allowing themselves to be spread so thin by all these different directions. They're saying, Hey, what's working? Is our heritage, what's working is our purpose. Let's keep our marketing and our brand true that let people use that brand how they will, but stay true to who we are.", "token_estimate": 559, "speakers": ["Andy Bethune"], "start_timestamp": "00:51:33", "end_timestamp": "00:51:33", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "88ef7c0a-1243-4c35-aa28-cf192fcc496f", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 24, "content": "Cole Heilborn (00:53:47): Yeah, I feel like a lot of this conversation has just been a case study on different brandings on different brands.\n\nAndy Bethune (00:53:52): Yeah. Well, I told you I'm a brand strategist, man. This is what I sit around thinking about all the time. I'm a weirdo as it relates to brands.\n\nCole Heilborn (00:53:59): No, this is good. So we talked about this idea of trying to avoid diluting yourself too thin, but still maintaining that sense of purpose. If I was a brand and I was looking around at all these other brands diluting a little bit, could I say, well, if they're all diluting a little bit, does it make more sense for me to niche into that core group to really make that my audience? Is there risk in that? Is there risk in not doing that?\n\nAndy Bethune (00:54:36): Yeah, there's always opportunity for those brands for sure. I think we've seen it happen over the years, brands that sort of feel like they can occupy a space that maybe has been left behind a little bit by brands that are trying to do something different or trying to go in a different direction. Just one that comes to mind for me right off the bat as we've been talking about North Face is the brand Polar and that brand has had some challenges. Are you familiar with that brand? P-O-L-E-R? They're kind of known for the Camp Vibes. No,\n\nCole Heilborn (00:55:16): I don't think I know 'em.", "token_estimate": 349, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:53:47", "end_timestamp": "00:55:16", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "3659a2a7-bedf-47ee-b0de-47a49e54c71e", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 25, "content": "Andy Bethune (00:55:17): Okay. Well, they were a really interesting brand. They've gone through some challenges. I think the brand, it sort of died out for a little while and then was bought by a different parent company and is maybe being revamped. But they were a really interesting brand that came into, at least into my sphere of brands maybe 10 years ago, eight years ago. And I think they really saw an opportunity to occupy a space that brands like the nor face weren't totally hitting. As those brands were like, okay, we represent Core Outdoor, but you can also buy us at Dick's Sporting Goods. And the authenticity was maybe missing that some of this more millennial Camp Vibes customer was looking for. And this brand Polar jumped in there and built this positioning around the fun, good times, affordable outdoor product is like you can have at a music festival. And they really jumped on the Instagram look, and they just really saw an opportunity for an audience that wasn't really being served by the big brands that were maybe some of the only options for that audience at the time. And I think they were really successful with that. (00:56:47): So yeah, I think that definitely as brands evolve and stretch themselves in different directions and there are always opportunities for other brands to come in, I think the big thing there is as the authenticity of the brand comes into question, there's a lot of room for another brand to come in with a more authentic story and say and be like, Hey, come check me out. In the Carhartt example, if you're like a true Carhartt connoisseur and you feel like Carhartt's kind of lost its way and been watered down all of a sudden, hey, here's Filson for you. If you want a brand that's real core, like Western Cowboy heritage and you really want to embody that and you feel like Carhartt doesn't do that for you anymore, I think that's how we're seeing the growth of a brand like Filson in some ways.", "token_estimate": 490, "speakers": ["Andy Bethune"], "start_timestamp": "00:55:17", "end_timestamp": "00:55:17", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "09d24d33-f644-496c-a31f-adf05a4778a1", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 26, "content": "Cole Heilborn (00:57:43): Yeah, interesting. This is a totally unrelated question, but I've had this question for a long time and I've always asked it of myself, of other people I've run into, and I'm curious just to hear your response just based on your experience with branding. Some companies do extremely well on a PL level without having a brand. They just sell product and they could argue, well, why do we need a brand we do really well. Why do some companies need a brand and why do some companies not need a brand? What's that distinction?\n\nAndy Bethune (00:58:25): That's a great question. So really, brands really exist to create differentiation in the market. So there are commodity markets where branding, where, let's look at toothpaste or salt or things like classic commodities where there's really not that much differentiation. I don't know about you, but I go to the toothpaste aisle and I'm like, I don't really care. This one's on sale. Well,\n\nCole Heilborn (00:58:53): Colgate has 50 options.", "token_estimate": 254, "speakers": ["Cole Heilborn", "Andy Bethune"], "start_timestamp": "00:57:43", "end_timestamp": "00:58:53", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "b694bd9a-5fae-4906-92b1-4cbde1922dff", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 27, "content": "Andy Bethune (00:58:56): Yeah, they all do. It's such a confusing, the CPG, the consumer packaged goods space is like men working in branding in that space is, I'm sure it must just be wild, but that's a great example of where they're building brands to try and differentiate those products. Outdoor apparel is honestly not too different at the end of the day. Sure, there's a lot of distinct high-end product. We've talked a lot about Alter so far. They make some really, really interesting technical functional apparel, high-end product, but a lot of the outdoor market is just buying wicking base layers, just average product that is not that differentiated. (00:59:47): So the brand is really there to help compete in a crowded market space and create some differentiation. The other thing that brands do is they create value. So I can sell you, there's a lot of companies out there that don't have strong brands that make really interesting product and you might see it at Costco or it's just an affordable price point, or it's like it's used in a lot of corporate merchandise, swag and things like that. Still good product, but the price point on it is low because the marketing investment hasn't been put in to create the brand, therefore the value equation just isn't there. So there's inherent value attached to brands their assets. It's for, I wish I knew the stats, but Coca-Cola, the worth of the Coca-Cola brand asset. That's the entire, so that's what makes that company. At the end of the day, it's just sugar water and there's all kinds of cola brands out there, but that's value and what you pay extra to have that.\n\nCole Heilborn (01:00:59): So some companies would say, when it comes to differentiation and providing value, sometimes that in itself is just reflective in how they price their products and how low they can price their products, the better we are because people are going to often choose the lowest option. I think about Amazon. Does branding matter on Amazon when you're just looking at reviews and you're just looking at that top page of stuff?", "token_estimate": 520, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "00:58:56", "end_timestamp": "01:00:59", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "014d6165-0035-4d2d-a38e-7e1a234005df", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 28, "content": "Andy Bethune (01:01:29): Yeah, man. So I'm not an Amazon expert, but you're tapping into a massive question here. And there are consultants and specialists in Amazon pricing strategies and branding strategies and things like that. But for sure, if you are going to buy a new jacket for a new ski jacket, I don't know. I don't want to speak for you, but for me personally, Amazon's not the place that I would go shopping for that (01:02:02): Unless I was price comparing. I would probably decide on the brand that I wanted to buy, the product I want to buy, and then I might find them on Amazon because they have that manufacturer or that brand has an Amazon strategy, I might find it at a good deal and maybe buy it there the two day or the prime shipping or whatever it is. But it's not where I'm going shopping for that. Whereas if I'm trying to buy a new phone charger where I don't care about the brand, that's where I'm going. So Amazon definitely occupies that space of selling a lot of commodity goods where the brand is not as relevant. But there are also brands that have built their entire brand off of selling on Amazon too, so it's\n\nCole Heilborn (01:02:46): Right.\n\nAndy Bethune (01:02:47): Yeah, it's a big piece to tap into.\n\nCole Heilborn (01:02:52): So why do you care about the brand that your jacket is, but you don't care about the brand of your phone charger? What about those two is", "token_estimate": 351, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "01:01:29", "end_timestamp": "01:02:52", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "26a36a48-e1a0-4852-a653-95143b92c9d6", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 29, "content": "Andy Bethune (01:02:59): Different? Yeah, I'm glad you asked that because as you were asking me that previous question, I realized something that's an interesting thing to speak about as it relates to why brand, why there's this intrinsic value in brands is that there's a lot of different types of brands and different reasons that people use brands, but one of the things that's common in the outdoor space is something we call an identity brand. And what that means is that I choose this brand because it helps me communicate something about myself and my identity. And there's a lot of value in that for people because a lot of people like to think that they don't, and there are people that don't make a ton of conscious decision about the brand of shirt that they wear or whatever, but most of us, whether it's conscious or subconscious, put a lot of time and energy into thinking about how we present ourselves to other people, what other people think about us, how the image that we portray to people, all those kinds of things and identity brands really leverage that to say a, to say, Hey, look, this is what our brand stands for. (01:04:14): This is what we represent. If you feel the same way or if you share these values and you want other people to know that these are your values, then we're the brand for you. And Carhartt's an interesting example of that. I think there's a lot of people that like that brand because they might not be doing a ton of welding or tree felling or something, but they like the idea of hard work and these classic All-American values, and that brand represents something to them. They're happy to show other people that they care about.\n\nCole Heilborn (01:04:51): Yeah. Interesting. Well, I wish we had more time. We're kind of running up against the end of our time for today. I know we kind of wandered a little bit, but I guess any closing thoughts, any closing remarks about any of the stuff we've talked about so far?", "token_estimate": 492, "speakers": ["Andy Bethune", "Cole Heilborn"], "start_timestamp": "01:02:59", "end_timestamp": "01:04:51", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "4dfb786b-75b3-4493-bddd-f71d0df09bd1", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 30, "content": "Andy Bethune (01:05:06): No, it was a really fun conversation. And yeah, we definitely covered a lot of ground. I mean, we started talking about the expanding audience of the outdoor industry, and then we ended up just having a really interesting conversation about branding in general. And I think it's really fun and exciting to talk about brands, and I'm sure for a lot of people who are in marketing feel the same way. So I'm glad we were able to have the conversation. I just think if there was a takeaway or something to distill, I think just encouraging people to really look at your brand as what's really at the core, what is that purpose or that DNA or that point of truth that is unique to your brand. And then as you face those pressures to grow and reach different audiences and expand product lines and things like that, use that brand strategy as your litmus test. (01:06:13): When we do brand strategy projects with clients, I think that's a lot of the inherent value of having a really well articulated brand platform is that you can constantly come back to that and you can evaluate business decisions against it because it's easy to evaluate a business decision against the p and l sheet and be like, look, this makes sense to sell this low margin product, and we could sell all this to Costco and all of a sudden look at all this profit or this extra revenue that we made from that opportunity. But if you go and look at that same opportunity and evaluate it against a really clean articulated brand platform and think about does it make sense with our values, does it make sense with our purpose? It might make you rethink that decision. And it might not always be a popular decision with stakeholders and with board of directors and things like that, but it's a long game. Branding is a long game, so sometimes you have to make sacrifices in the short term to achieve those long-term gains.", "token_estimate": 478, "speakers": ["Andy Bethune"], "start_timestamp": "01:05:06", "end_timestamp": "01:05:06", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "87abe2d1-871c-4c0d-952c-84bfd711bb4a", "episode_id": "874b072f-0d9c-4887-b868-4082bce7a212", "cms_item_id": "68225dfc7bb476527f8c4866", "chunk_index": 31, "content": "Cole Heilborn (01:07:18): Yeah, well said. Well, Andy, I know I have more questions. If people who are listening have more questions around this conversation and they want to learn more about Origin or if they just want to hit you up for a Zoom call or a beer, where can people go to find you or Origin?\n\nAndy Bethune (01:07:35): Yeah, absolutely. So you can definitely check out origin@originoutside.com. We got a lot of fun case studies and videos, and we also have a pretty active blog that you can sign up for a newsletter. I think once a month. We put out a newsletter with usually at least three or four pretty interesting pieces of content around outdoor industry marketing. It's definitely encourage anyone who's interested in that to check that out. Me personally, you can find me on LinkedIn, Andrew Bethune, touch base with me, shoot me a message connect. And yeah, always happy to chat branding and outdoor sport and outdoor industry marketing with like-minded folks, so I appreciate the opportunity to jump on the podcast.\n\nCole Heilborn (01:08:27): Yeah, thank you again. This was a lot of fun and I appreciate you sharing some of your perspective. And I think if anything, again, I feel like every episode I just end it feeling like, well, there's no right answer. You just have to just do your thing,\n\nAndy Bethune (01:08:42): Man. I mean, that's just it, right? We started out talking about how marketing is art and science and there, there's science to it for sure. And a lot of the direction that we've seen the industry go lately has been maybe more focused on the science side of it than is arguably appropriate, but a lot of it is art, and there's no right answers, and you nailed it. It just comes down to constantly trying to just understand what resonates with the fickle consumers.\n\nCole Heilborn (01:09:13): Yep. Yep. Well, awesome, Andy, I look forward to seeing the work that you guys do in the future, and thank you again for your time, and I hope you have a good rest of your day.\n\nAndy Bethune (01:09:22): You too, Cole. Thanks a lot. Appreciate the opportunity.\n\nCole Heilborn (01:09:24): See you.\n\nAndy Bethune (01:09:25): Bye.\n\nCole Heilborn (01:09:28): Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learned something new, please consider leaving us a review on Apple or sharing this with a friend.\n\nSpeaker 3 (01:09:44): I.", "token_estimate": 607, "speakers": ["Cole Heilborn", "Andy Bethune", "Speaker 3"], "start_timestamp": "01:07:18", "end_timestamp": "01:09:44", "podcast_index": 65, "episode_name": "EP 65: Andy Bethune | Something to Everyone | Origin Outside", "slug": "ep-65-andy-bethune-something-to-everyone-origin-outside", "web_url": "https://www.portsidepro.com/podcast-feed/ep-65-andy-bethune-something-to-everyone-origin-outside", "guest_name": "Andy Bethune", "guest_title": "Director of Strategy, Origin Outside", "categories": [], "short_description": "As people flock to the outdoors, many brands are welcoming and embracing these individuals with open arms. Brands that were once reserved for core users are breaking down their walls to be seen as a more inclusive brand.", "podcast_length": "44:87"}, {"id": "dee7868f-e476-4be8-98db-d03960a21352", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 0, "content": "Shaun Durkee (00:02): And through the pandemic, what changed? What evolved?\n\nCole Heilborn (00:07): Everything changed for me. Everybody at work that knew I got laid off, they'd say, oh, I'm sorry to hear that, but are you going to work on AL and Fuel? Are you going to work on your side business? And within a couple of days, the answer became yes. Yes, we are.\n\nShaun Durkee (00:29): Welcome to the Backcountry Marketing podcast. My name is Cole Helebo and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam or cracking a local beer. I hope you enjoy today's episode. This is the Backcountry Marketing Podcast. This episode is produced by Port Side Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Helebo, and today I'm sitting down with Sean Durkey, the owner of Alpen Fuel. Sean, how are you?\n\nCole Heilborn (01:09): I'm great, thank you. Thanks for having me on.\n\nShaun Durkee (01:12): Yeah, thanks so much for taking time out of your day to join us. You're calling in from Bozeman, is that right?\n\nCole Heilborn (01:20): Yes, Bozeman, Montana, just about an hour and a half north of Yellowstone National Park.\n\nShaun Durkee (01:25): Beautiful. I'm actually going to be taking a road trip sort of your direction in this next week. We're going to go down to Utah, so we're going to cut through down in the Yellowstone area. Yeah, we're looking forward to getting out of the Washington. Well, it's actually sunny now, but the historic rain during the winter.\n\nCole Heilborn (01:44): Yes. We've had a lot of wind and rain, a little bit of snow. It's just been a typical march for sure. But we're looking forward to a warmer spring.", "token_estimate": 487, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "00:02", "end_timestamp": "01:44", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "4fe37298-76ff-45c3-b9e3-d5d619bba5c4", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 1, "content": "Shaun Durkee (01:52): So I'm excited to have you on the show for a number of different reasons, but I'd love if you could give us a little bit of background on Alpen Fuel, who you are. We have a lot of brands and companies on this show who tons of people have heard of, they're household brands, but Alpen Fuel is a really new and exciting company that you and your family have just kind of picked up and are getting started. And so I'm excited to dive a little bit into your startup journey where you guys are at, but could you give us a little bit of a background on what you do?", "token_estimate": 146, "speakers": ["Shaun Durkee"], "start_timestamp": "01:52", "end_timestamp": "01:52", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "1b53d883-20ba-4b21-b18d-bc167eeabced", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 2, "content": "Cole Heilborn (02:25): Sure, yeah. Thanks again for the opportunity. Like you said, we're extremely small. We're probably the smallest company on your podcast so far, but it's me and my wife working out of our house, and we're a backpacking food company. We have a food store currently where we offer about 15 to 20 different brands of backpacking food, and we offer everything from meals, snacks, drinks, kind of a one-stop shop. And that's how we got our start was as a side business. And maybe I'll just go into a little bit more about my background and then talk more about the business, but I'm a fifth generation Montana guy here in Montana and Bozeman and I grew up hunting, fishing, backpacking, doing all the normal Montana stuff. And that's really where my love and my passion has been over the years. But I came to MSU Bozeman here and studied engineering, industrial engineering. (03:22): It's just the how to make manufacturing more profitable, more efficient, things like that, production scheduling. So that's where my background was. And right after college, about half of my graduating class got hired by the Boeing company in Seattle. And so I moved out there for my first two years and worked on the 7, 7, 7 aircraft and the 7, 8, 7, the brand new at the time, I got to work on the first five of those airplanes. So that was pretty exciting. But I never really got away from my love of Montana and my family's still here. So after two years there, I moved back to Bozeman and I got married as a time and then started working for an optics manufacturing company. And we made laser assemblies for industrial medical lasers, range finders, that sort of thing. And I've always enjoyed manufacturing. And I guess one thing I omitted before I started my role with FLIR Systems, which was doing the optics and the laser manufacturing, I went to grad school. (04:30): And at that time I studied entrepreneurship and small business management in addition to engineering. But I had an interest in the engineering side, but I was always interested in the small business side because I'd worked with Boeing, but also with smaller companies over the years and really seen that difference. The small company entrepreneur style was really appealing to me, but I didn't quite know how to use the entrepreneurship side. I just got another job with a corporation at that point, and I worked there for nine years. And then as that time went on, I moved up and down in the business. I became a manager for a while and got to fire people and go through all that, the rigmarole of being a manager and the stress with that. But I didn't really identify with what we were making. It was kind of parts, pieces that got shipped all over the world to get integrated into assemblies. (05:25): And so I wasn't really connected with the product, I didn't understand the physics behind it to put it, frankly, I didn't really enjoy my work at all. It was getting to be a burden. And so that's when after seven years working in that capacity, out of my nine year tenure there, we started LP and Fuel and we just started as a side business. Like I said, we stocked a lot of brands for other products. We were dealer and we went with that. We started with the store side, which I've explained, and then we also, we decided, no, let's try two ideas and let's see what works. And so we stopped the store with small brands, and then we also tried a subscription box company with back country food for hunters, backpackers and the like. But because we were so unknown, we didn't have any presence really on social media that was sizable. (06:19): We didn't have a good newsletter following et cetera. So that business just was a flaw. It didn't do well at all. So we got out of that after 10 months and just said, let's go with our food store. That's what people have been using. Subscription box, well, we made some connections, but let's just cut our losses with that. And we moved on. We were just getting pounded by bigger companies that could ask for bigger discounts. We couldn't put enough value in the boxes, that sort of thing. So that was where we were at through 2008 and largely into 2009. And then the pandemic hit at that point.", "token_estimate": 1056, "speakers": ["Cole Heilborn"], "start_timestamp": "02:25", "end_timestamp": "02:25", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "12c49c2a-3796-4100-98ae-6e0fb013f146", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 3, "content": "Shaun Durkee (06:57): And through the pandemic, what changed? What evolved?\n\nCole Heilborn (07:02): Everything changed for me. I was one of 22 people in my branch of the optics company and my dissatisfaction I guess was known. I talked to my boss and said, look, this had been over the last two years. I said, I'm looking at leaving. I just want to give you fair warning. We started cross training the employee that I had at the time, and they were really prepared for it. I was just looking for what that right opportunity was. And then with COVID, a very large portion of our revenue stream died up. The medical instrument companies, they weren't getting freedom to invest in capital equipment purchases, all of this. So as many others, I guess my position was eliminated. I was one of the administrative staff that downsized and then some of that were building. The products were downsized as well. So very quickly after getting called into a conference room for a meeting, I found myself with two weeks left to work at a position I'd had for nine years that paid the mortgage and that I was comfortable in. (08:13): And so we scrambled. The interesting thing to me, everybody at work that knew I got laid off, they'd say, oh, I'm sorry to hear that, but are you going to work on AL and Fuel? Are you going to work on your side business? And within a couple of days the answer became yes, yes we are. And so after sitting down with my wife and a panic, what do we do? How are we going to manage what's next? We decided, well, we have this small business. It's not at that point, we'd basically put all of the profits of the company back into the company. It was still really small. So our thought was, if we are going to really make a go of this, this is our golden opportunity. The company I was with was generous enough to give me a little bit of a stipend, a COVID stipend when I left. (09:04): So we had a little bit of money to live on and I had the time and opportunity to work on the business, but our thoughts went too, well, we have these other brands that we're carrying, but I didn't see a path forward and how to be competitive with all of the other stores out there. And our thought went to, let's develop our own brand further. Let's invest in ourselves and try and get the Alpen Field brand up and going. And so we sat down and developed a line of breakfast products. And so that was our summer. I guess this happened in July of 2020, and my last day was the day before Independence Day. And then we were full-time on ALP and Fuel after that.", "token_estimate": 640, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "06:57", "end_timestamp": "07:02", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "5abc33a5-b038-4454-ab36-d54ed2baf3e2", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 4, "content": "Shaun Durkee (09:48): So pre COVID, you were running Al and Fuel kind of this side hustle that you were distributing other products through your e-commerce store. Then COVID happens, you lose your job, and then within a couple of days you said, Hey, well, I might as well just try going full-time with Alpen Fuel. When you lost your job or when you were thinking about leaving your job, did you ever have the intention of turning Alpen fuel into your full-time job?\n\nCole Heilborn (10:18): Since the beginning? That's always been in the back of our minds, but we had never, I guess had what I thought was a great product idea or the timing was never quite right. We were trying to grow it steadily over time, and then all of a sudden it's like, okay, we're not ready to jump to this business, but we have to. So let's see how quickly we can scale this thing. And so in the months leading up to the layoff, I guess certainly I'd been thinking about other product ideas and whatnot, but we didn't really have a clear direction at that point. So that kind of crystallized, I guess with the layoff. And over the last, or the four months after that, when it took us four and a half months is all to get a product line off the ground, which I think was pretty quick compared to some of the other companies that are out there. (11:05): And they may spend one to two years. But we picked a simple product line that we could get off the ground fairly quickly and then just spent every waking minute trying to push that to completion. And so that process was fairly interesting. We had a lot to learn with it, but we picked, our products that we picked were just simple breakfast granolas, and so they're baked products and there's other products on the market that I liked, but I was trying to improve, I guess coming from an engineer mindset, I was trying to get my wishlist of everything that I wanted in the product and then trying and check all of the boxes. And so we have a product that contains powdered milk, so you can prepare it with hot or cold water. It's ready in five minutes. And then we combined a lot of fats with the carbs so we could get a really high calorie to weight ratio. (11:57): So the breakfast that we designed are 630 to 770 calories. They're the biggest, largest by calorie breakfast on the market out there. And they're really designed for endurance activities like through hiking or people who are putting on a lot of hard miles every day, back country hunters, that sort of thing. So we developed that product. We picked four recipes and then sent them out to our test group, and we had everybody from hunters to ultralight backpackers, and we had one endurance coach, a Montana endurance coach that coaches cyclists and ultra runners and that sort of thing. So we had a great group to give us feedback. We iterated quickly and then continued on with the process. And that process, there's nothing really written down that I could tell about how to develop a food product. We just got in it and started throwing punches I guess. (12:54): But we knew that we would need a label and nutrition facts and all of that. So we contacted a lot of design folks and got quotes between 10 and $40,000 to design four pouches, and that just wasn't in the cards for us to pay that much money. So we backtracked and actually I jumped in with a bunch of YouTube videos and bought Adobe Illustrator and with the help of some other marketing folks that I'd made connections with, just got in and started making the design for the pouches. So we got that ready and then we tried to submit it to the state, and in that application form, it outlines a bunch of other things that we needed. So they told us, well, you need to take food safety courses. We got that lined out. We had to send the food to a lab in Oregon to get tested for shelf stableness and a whole bunch of things like that. (13:50): We got set up through the city county and got a kitchen lined up that we could produce out of to rent by the hour. And so those four months were just filled with those type of tasks. But it's nothing obviously is as straightforward as it seemed. Every step of it was a little bit harder than I thought it'd be. Just if, for example, the nutrition facts on the back of every food product from the FDA, there's 132 page PDF that governs what can be in that nutrition facts and the food labeling in general, the label, the front and the back of the pouch. So we had to mine through that, figure out our tech sizes, fonts, what words we could and couldn't use all of that. So that was an interesting learning process there. But eventually four months later, we were able to get off the ground and get our first sales and get product into the hands of consumers.", "token_estimate": 1190, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "09:48", "end_timestamp": "10:18", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "99e1493b-4c19-45a9-8321-90b9a0d83c32", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 5, "content": "Shaun Durkee (14:46): That's incredible. When you look back, is it pretty mind blowing, seeing how much you were able to get done in that short amount of time? I mean, you're listing packaging, kitchens, all of the testing, all of the certifications that you need to go through. What was that like?\n\nCole Heilborn (15:04): It was fairly arduous, I guess. Just we didn't know what we didn't know. So we went through the food safety class and tried to submit our labels and they said, well, where's how many? I don't remember. It's parts per million or whatever. What's your water activity level on this food? It's got to be below a 0.8 or whatever the cutoff is. And I said, well, tell me more about that. I wasn't aware we needed that. So then we talked to the state labs and everything and got that approved. I think we had all of the motivation to do it in a short amount of time. I mean, this is everything financially for us was riding on this, getting this off the ground. And so we had every motivation in the world. I finally had carte blanche time-wise to just spend all the time that I had been working at my prior job. (15:56): Everything was freed up just to work on this one task of getting this thing off the ground. So we put everything we had towards it and it went fairly quickly. But yeah, lots more steps than I realized. We had to look at maybe almost 10 commercial kitchens before we landed on one that we liked that we could work under their management well and so on. So I think having all that time was a blessing, and I never could have done that if I was employed full-time somewhere else. It took, you hate to say it, but I don't think the part-time was ever going to become a full-time while I was working somewhere else. It took a big event like this to just get it jump started and allow me to put all my effort and time onto it. So it's been a blessing for sure from that regard. But now that we're trying to introduce a second product line and doing research towards that, we have some ideas about the products, but now that we're in full production mode with the granola, we don't necessarily have as much time to invest. So I'm seeing the difference now that I don't have as much time. It's certainly a clearer path to get to the end, but just finding all the time now is more difficult.", "token_estimate": 580, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "14:46", "end_timestamp": "15:04", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "33972449-ff2b-4fbc-b754-71688d238ee0", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 6, "content": "Shaun Durkee (17:09): How does your connection, you alluded to it, how does your connection with your interest and your passion for engineering, which has been up until recently, your focus I guess, was that a natural transition for you? And if so, could you kind of break that down? How does engineering apply to food manufacturing?\n\nCole Heilborn (17:32): That's a great question. My background specifically, like I mentioned, was working in the aerospace with fifth Boeing and then more recently with flir. They're out of Portland where we built the laser optics. They're largely assembly operations, and those type of companies don't have to do a lot of marketing because they make something that just a handful of companies in the world make. So people come to you, they do a couple trade shows a year, but they're well known in the industry. And with food, it's more of a commodity. So I really had to wrap my head around that. I guess the manufacturing side, I'm well versed in how to make things more efficient there, at least how to think about it. I was able to cost the products out nicely. That might be a struggle for someone, but that's the world I lived in was how profitable are these things? (18:25): What are our margins? How can we tweak things to be more profitable? So that was a fit, but the marketing side, how to do a newsletter, thinking about social media, running online, giveaways, that part was foreign. I had a lot of learning there to do some of the design aspects, but the networking side, I wasn't completely foreign to. I know a lot of engineers tend to live in a bubble maybe, and they do design, but that was never, I picked industrial engineering because it's the most people oriented version of engineering. So I was schooled in business classes and things of that nature, but while I was working at FLIR Systems, I was in charge of interacting with all of the dealers isn't the right word, the suppliers that we had that put coatings on our optics or machined them in certain ways. So I was used to dealing with a lot of different things, a lot of different irons in the fire. And so right now I am dealing with dozens of companies throughout the weeks. And so that part I really enjoy and is more of a natural fit based on my background. But I'd say the type of engineering background that I have was well suited for where I'm at now.", "token_estimate": 594, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "17:09", "end_timestamp": "17:32", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "62f723f0-6e0f-4f9f-a816-8b5a05035e4f", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 7, "content": "Shaun Durkee (19:41): Yeah, that's interesting to see how those dots connect. So I'm curious, you mentioned a couple years ago you started the food box subscription\n\nCole Heilborn (19:53): Deal,\n\nShaun Durkee (19:54): And one of the reasons why that wasn't successful is because, as you said, no one really knew that you existed. How do you get the word out now about Alpen fuel if that's a challenge you faced with the previous business going into Alpen Fuel a year ago? I mean, I'm sure that was in addition to making sure you actually are able to develop the food and get all the certifications, there's got to be the back of your mind. You're thinking, if we do all this, then we actually need to have people find it and purchase it, and we need to be able to get ourselves out there. I guess how have you managed that?", "token_estimate": 206, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "19:41", "end_timestamp": "19:54", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "76384e27-c8c0-48bb-b78d-3399cd3ef701", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 8, "content": "Cole Heilborn (20:33): That's a great question. Just to give people a little bit of perspective or context on the subscription box. Like I said, we ran that for 10 months, and this is embarrassing to admit, but I haven't even really shared this with anybody. The best month that we ever had on that was selling nine boxes. It was pathetic. We lost money on it every single month. We gave more boxes away than we ever sold. There was other companies out there that maybe the person that ran them maybe had a podcast, so they had an audience to market to. We had a hundred newsletter subscribers when we started the business. And so our sales reflected that it was, we weren't prepared. I didn't fully understand the effect of our reach at that point. You just assume that you create a product that has value and people will flock to it. (21:30): And I was dead wrong on that. So I had a lot of growing up and learning to do there. So over the course that first year, we didn't really grow our newsletter subscribers that much. We just tried a few things and stuck with the business model of having the online store. And then it was in the second year, 2019, where we decided, okay, we really need to get more eyes on our brand. Nobody knows who we are. We're still completely unknown, we're still unknown at this point, but at least we have a little bit of a following. So that year, I decided after doing some research that online giveaways with social media would be a way that we could grow our following. And so we started doing those Instagram only type of giveaways in the beginning with two or three brands, and I just slowly leveraged my way. (22:22): I picked a brand that we had in our store and they said, sure, let's do one. And we got a couple hundred Instagram followers out of that one, and they'd be 30 to $40 worth of product, and we'd leverage that into more brands. And then I decided after more reading, if we are going to grow our newsletter following, which appears to be one of the best options for direct to consumer sales, far better click through rates and sale rates than just an Instagram post, for example, if we're going to do that, we need to get a much bigger newsletter following. So we switched over to doing bigger giveaways with companies, and the first one we did, I think was in August of 2019, and my thought process there was, we're the smallest guy in the room. Why should anybody work with us? We're not going to get invited to any giveaways with other companies. (23:16): We've got to do this ourselves. And so I took it upon ourselves, my wife and I, just to kind of lead the charge there. And so we started doing not quite monthly giveaways, but several throughout a year where I went out and I took on, we went through gleam.com, I guess is our first one, but that's just, they help create the landing page and the code that you can embed in your website to collect email addresses for these giveaways. So instead of just getting Instagram likes, we just thought, well, let's do a much bigger prize and collect this data from people and get their email. So that's what we did, and it's worked really well. We've done that now, this'll be our second year in doing that, but it's been great. We're actually launching a giveaway next week, excuse me, two weeks out, and it's going to be 14 brands and about 3000 in prizes. So I was looking through folks that have been on your podcast and saw a lot of folks I've worked with from oru, kayak and Duckworth and Clean Canteen and others. So we just try to leverage our network, get these other brands online and give away much bigger prizes. And so that drives website traffic for us. We get recognized with our logo alongside all of these other big brands, and it adds legitimacy to who we are, but people still don't realize that I'm creating those campaigns in my guest room here at a fly tying bench.", "token_estimate": 974, "speakers": ["Cole Heilborn"], "start_timestamp": "20:33", "end_timestamp": "20:33", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "96b2e936-5784-4597-ab78-c57c0a0dbc10", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 9, "content": "Shaun Durkee (24:55): Oh my gosh, I love that. I love that idea of trying to ladder up and play a league up from yourself. Yeah, I think that's sometimes what it takes. That's pretty cool to hear that that's worked out for you, and that hasn't been something that you've looked at and said, ah, I don't want to try to go and ask that bigger brand if they want to partner with us. But just having the gumption to go out and reach out I think is pretty cool.\n\nCole Heilborn (25:25): Yeah, it's been great. I think it's one of the smarter decisions we've made was to do that, and it's low cost for us, and we message dozens and dozens of companies, and a small percentage of them actually are interested in sign up. And now we've got folks that have been in three, four or five, six giveaways with us. So we're helping brands now that we're kind of a middle player as far as newsletter size goes, we can help brands that have zero following by getting them involved in the giveaways too. So we're able to give back and create a lot of value for these companies, and they've given us great positive feedback and we're going to keep doing it. So it's been great.\n\nShaun Durkee (26:07): I think for every small business owner, all the time and energy that you put into your business in some way or another, it has to come back and you have to hopefully recoup that time that you spent ideally in the form of sales. As you spent all of this time just trying to figure out the newsletter thing, the giveaway thing, are you starting to see the results that you hope for? Are they results that you didn't expect? I guess? What have you learned from those results?", "token_estimate": 414, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "24:55", "end_timestamp": "26:07", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "06e129ae-0f10-495e-b543-9df313728d88", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 10, "content": "Cole Heilborn (26:40): We learned, I guess when we did our product launch for our granola last October, we did a presale for two weeks. And so now that we had a good track record with these people, we'd been emailing them a couple times a month. They knew who we were. When we decided to tell people that the best email response we've ever gotten was the one that I sent out that said, we're creating a food brand. And that was the one where it was just a lot of texts telling people, here's what's happened in our lives. We've got laid off, but we're going all in on this opportunity to create our own food products follow along with us. And so we kept people updated on that leading up to our launch, and we had a tremendous response launching a product in November in the dead season. We were just overjoyed with the response that we got, but at that point, we were marketing to thousands more people than we were when we launched our brand back in 2018. And these people had followed along with us, and really the story resonated with them. So it was night and day, I guess, from when we launched the company to our first product launch a couple years later. So that was tremendous. And then this year as we develop new products and bring on new brands into our store, we can communicate that immediately with people, and they're obviously people that have consented with us to a market to them. So it's a great audience and a low cost for us to do that.", "token_estimate": 365, "speakers": ["Cole Heilborn"], "start_timestamp": "26:40", "end_timestamp": "26:40", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "7b2f6807-f465-49dd-94fb-b65ebba00110", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 11, "content": "Shaun Durkee (28:16): Sure. Yeah, that makes sense. What I find really interesting is your background, again, is not marketing per se. You mentioned you've always had this kind of passion, this interest for entrepreneurship, and then it was this kick, this that kind of kicked you out of necessity into dumping more fuel into the fire. Was there ever a point though where you felt overwhelmed or just mean marketing in itself is something you can spend your entire life doing, not to mention everything else that you're doing running the business. What I think is unique and what I like about your story is that you just kind of jumped in and said, well, we'll figure it out, whether that's downloading Illustrator and then watching YouTube videos to figure out how to make your packaging. I guess I'm just curious, what's your mindset around all of these challenges that you've kind of had to dive into out of necessity?", "token_estimate": 231, "speakers": ["Shaun Durkee"], "start_timestamp": "28:16", "end_timestamp": "28:16", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "f0d6f7fb-e0f4-4c8d-818e-0ce15fd4ce88", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 12, "content": "Cole Heilborn (29:20): That's a great question. I would say my mindset, my wife and I when we were in college or when we got married, rather, we totaled up how many jobs we'd done between us, and I think the total was between 30 and 40 at that point. It was crazy. I've always been interested in random things. In college, I worked at a feed store selling pig food, and I had never pig and cow food, grain bags, that sort of thing, bird food, dog food, and I'd never been exposed to any of that. So I tried to learn as much as I could so that I could sell people the right products. I worked as a bank teller. I worked for a log home company, just a crazy amount of things, putting in sprinkler systems, so I wasn't a stranger to learning new things. And I think I changed jobs a lot in college out of necessity, I guess seasonal jobs, that sort of thing. (30:19): But when I worked for Boeing for two years and then at the Optics company for nine, those were the longest jobs I'd had by a long shot. So I am used to bouncing around and learning new things. I don't consider myself really a stereotypical engineer. I have some of a mindset for design of buildings or something like that, but I'm more scatterbrained than that, I guess. I like to go in different directions and learn new things. So it was fine for me to, I knew the resources were there on YouTube or talking to other marketing folks. I'd say I've gained a lot of respect for other entrepreneurs and folks in the marketing community because now it was an unknown to me. Like I said, working for big companies, my whole job was to make production lines more efficient. I didn't get involved in the marketing side or the trade show side or social media or any of that. So it was just this complete unknown, I guess, for a lot of years. And I had some inklings about it, but jumping into it has been a lot of fun. I've learned a tremendous amount. And like you said, marketing's one of those bottomless topics that changes frequently, and it's tough to be on top of, but it's one of my favorite parts of working as an entrepreneur.\n\nShaun Durkee (31:42): Where do you want Alpen fuel to go? What's the goal? What's the vision?", "token_estimate": 548, "speakers": ["Cole Heilborn", "Shaun Durkee"], "start_timestamp": "29:20", "end_timestamp": "31:42", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "82e1b1fc-10f4-469d-93dd-05b7d85f3d93", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 13, "content": "Cole Heilborn (31:47): The vision for our company in the near term would be just to be sustainable. We're still working towards being profitable, and we're still in that investment stage. So we invested all last summer in the business. We were building ahead on products for the winter and going into the trail season, and we're just looking to have the biggest or the best trail season that we can have this year and introduce other products so that we just have a more diverse array of things that we can sell folks and be valuable for them on their trips. So in the near term, I'd say this year that's the goal is just to get through our first trail season so that we have better forecasting going into next year. We know how to make our products and know what to expect really, and then just continue to add products and expand our dealer network. That's one part of the puzzle that I've worked on this winter with the help of some other folks, how to expand our dealer presence. And so that's been uppermost in my mind. We're in about eight different stores right now, so still just a lot of potential to grow what we have, and so we'll just look at different ways to capitalize on that.\n\nShaun Durkee (33:04): And just to be clear, remind me again, but it's just yourself and your wife that are every week, week in, week out, making the food, baking the food, packaging, and then distributing, right?\n\nCole Heilborn (33:17): Yes. We're doing everything from top to bottom, so we share half and half the load in the kitchen. We work mornings in the kitchen, and it's actually a restaurant that sells food to kind of a pay as you go operation for folks that are low income. And so they work afternoons creating meals for those folks for dinnertime. And then we just rent the kitchen in the mornings. So we're in there four days a week currently. And yeah, it's just my wife and I splitting the tasks, shipping everything and trying to hustle every day.\n\nShaun Durkee (33:53): Wow. A year ago, did you ever anticipate yourself being in the position you're in now?\n\nCole Heilborn (33:59): Absolutely not. No.", "token_estimate": 528, "speakers": ["Cole Heilborn", "Shaun Durkee"], "start_timestamp": "31:47", "end_timestamp": "33:59", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "44eedad5-af9d-4ffe-81a5-10260e8e84bf", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 14, "content": "Shaun Durkee (34:02): You lost your job. You then said, well, I guess now's the right time to jump into the side business, but you could have very well just said, well, I'll just find another job. Amidst all of the uncertainty around the pandemic, jumping into more uncertainty by starting a small business that, I mean logically doesn't make any sense, but emotionally, I mean, I understand. I think where you're coming from. I guess I'm just curious, how did you feel that this was the right thing to do?", "token_estimate": 127, "speakers": ["Shaun Durkee"], "start_timestamp": "34:02", "end_timestamp": "34:02", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "ae4d7550-569d-49bf-810e-6a403f15affe", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 15, "content": "Cole Heilborn (34:41): Oh, wow. That's a great question. The right thing to do. Well, I had worked on the business for a very long, well, very long time. For me, I'd worked on the business for a couple of years, almost two years at that point, and I'd worked on it basically for free on evenings and weekends, and I had never lost interest in it at all. So I thought, this is something that I would love to spend all of my time on. It's something I'm super passionate about. When I was working for these other companies, I guess Boeing in particular, everybody there that, oh, you're from Montana. Well, you must hunt. So then the conversation naturally went to hunting. Nobody ever wanted to talk about what they were doing at work. They wanted to talk about the things they love to do in their free time. And so I've decided those are the kind of products that I want to make. (35:35): The stuff that people are using on their best days, not a wrench that you're using when you have to be at work, those aren't the type of things that you remember. Maybe your working days at the end of your life, it's the other time in between how do you spend your time when you have free time, what do you spend it on? You spend it on what you love. And for me, that was the backpacking, the hunting, the fishing. So sharing in that experience with other people was really valuable for me. But I think I felt a license to be able to work on it simply because we got a little bit of a stipend, the COVID payout, I guess you'd call it from my prior employer since I'd been there nine years, and I managed one employee. It was a good sized at the time. (36:26): It felt like this is a few months where I can not worry about my bills, where I can devote a hundred percent of my energy to working on this business. And so at that time, I gave myself a year. I said, if I can work on this and it's got enough legs a year into this thing, then let's keep doing it. And that year will be this summer. It's kind of like having a baby in a way, because you can have really good highs and lows all on the same day. My wife has been tremendous in helping, well, both of us trying to help each other, but more so her helping me. I guess. Just an example, two weeks ago, I was pretty low and frustrated with everything. We've been paying out, I guess, through this winter to get product ready to go for trail season, so that's expensive. (37:18): You're paying kitchen rent, you're buying pouches, and you don't know what your demand's going to be in the summer. And so our dealer network was growing slower than I'd wanted, so I was pretty frustrated, and I sat down with my wife to tell her all the reasons why we shouldn't be in this business. It's one of those things where the pendulum, it swung, and I was on the woe is me. Here's what's not working side at the time. And so we talked through that a little bit, but during that conversation, she went up to help the kids during their nap and came back down, and we got two of the biggest orders that we've had ever in a three day time period. We sold almost a month's worth of production. (38:02): All that back stock that we had, that I was worried that we wouldn't be able to sell. We just blew through it. And so that was reaffirming to me, Hey, I think we're on the right path. And so that, I'd say out of all of the last several eight months, that two week period to me was I was doubting what we were doing and where we were going. But I'd say the rest of the time we've had pretty firm convictions about where we're going and hopefully our ability to get there. We've had a lot of help from other people as far as bouncing ideas off of people and just nice words on Instagram inspiring us to keep going. And so it's largely, we've kept inspired and kept a goal and view, but obviously with any business, there's times when doubts creep in and things like this.", "token_estimate": 975, "speakers": ["Cole Heilborn"], "start_timestamp": "34:41", "end_timestamp": "34:41", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "b09ab80d-5d2c-4835-9718-44fa2b99fd1f", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 16, "content": "Shaun Durkee (38:57): Sure. I mean, that's inevitable. Yeah, man, I love that. I appreciate you sharing. I'm sure there's a lot of challenges that you see on the horizon, but if you had to limit your selection of challenges, I'm curious, when it comes to marketing, what's the current hurdle? What are you trying to figure out? If you could wave a magic wand and solve blank, what would that be?\n\nCole Heilborn (39:26): If I could wave a magic wand, what would I solve for us? We're going to get into the digital marketing space, I guess more this year. And so that's kind of our next challenge that I'll be facing in the next couple of months. How to, the challenge I guess for me is still just how nobody knows who we are, so how can we get in front of as many eyes as possible? And that would be one piece of that that we're trying to solve in the near term would be the digital marketing piece.\n\nShaun Durkee (40:07): Yeah, yeah. No, that's a beast. Yeah. I wish I had all the answers for you, but it sounds like with the rate that you guys are going, you will overcome those as well.\n\nCole Heilborn (40:20): Yeah. Thank you for the optimism. We need it.\n\nShaun Durkee (40:23): No, this has been great. Unfortunately, we're running out of time for today, but if people want to follow you, if they want to follow along with the brand, or if anyone who's listening has any thoughts about how to, I dunno, help give thoughts to Sean and his wife as they're embarking on this awesome journey. Where can people go to connect with you?\n\nCole Heilborn (40:47): They can email me directly at LP and fuel@gmail.com, or they can go to www lp and fuel.com, or they can find us at LP and Fuel on Facebook and Instagram.\n\nShaun Durkee (41:03): Great. It sounds like if you wait around long enough, you'll have some giveaways that people might be able to partake in.\n\nCole Heilborn (41:10): Yes. For our current schedule for 2021, we did one in February, we'll be doing one in April, which is in the next two weeks, I guess, as of this recording. And we'll be doing one in June and one in September.", "token_estimate": 523, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "38:57", "end_timestamp": "41:10", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "3b37f1f6-4606-4be5-a3eb-b4d73ef11087", "episode_id": "f63849af-7ad6-4fd0-8306-9fd82bff53c8", "cms_item_id": "68225dfc7bb476527f8c4864", "chunk_index": 17, "content": "Shaun Durkee (41:25): Okay, wonderful. Well, Sean, I really appreciate you taking the time out of your busy day as you're still trying to get this thing up and running. I think your story is pretty inspirational, and I hope that for any folks who are listening out there, yeah, just pull something from Sean's tenacity as they're driving forwards and try to make this thing happen. And it sounds like you are one step at a time. So again, congratulations.\n\nCole Heilborn (41:50): Yes, thank you, Cole, and thanks again for the opportunity to be on your podcast.\n\nShaun Durkee (41:54): Yeah, of course. Well have a good rest of your day and I hope you have a good spring.\n\nCole Heilborn (41:59): Alright, likewise. Thank you, sir.\n\nShaun Durkee (42:01): Take care. Thank you for listening to this episode of the Backcountry Marketing Podcast. If you enjoyed today's episode or learn something new, please consider leaving us a review on Apple or sharing this with a friend.", "token_estimate": 243, "speakers": ["Shaun Durkee", "Cole Heilborn"], "start_timestamp": "41:25", "end_timestamp": "42:01", "podcast_index": 66, "episode_name": "EP 66: Shaun Durkee | Slow and Steady | Alpen Fuel", "slug": "ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "web_url": "https://www.portsidepro.com/podcast-feed/ep-66-shaun-durkee-slow-and-steady-alpen-fuel", "guest_name": "Shaun Durkee", "guest_title": "Founder, Alpen Fuel", "categories": [], "short_description": "One step at a time", "podcast_length": "44:88"}, {"id": "4a853e50-0322-4ae7-b010-a298d4dd190a", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 0, "content": "Chris Dickerson (00:00:02): At a previous agency, creative agency that I worked with, we were the agency of record for Hydro Flask at the time, and I thought they did a really good job of understanding the product, lifestyle, and the consumer lifestyle, creating that customer persona and the profile to match those two together to make sure when they were ready to launch and go to market, they had everything, all their ducks in the line and all their channels built for to have a really successful launch. So I always felt they were pretty dialed in that realm of things.\n\nCole Heilborn (00:00:33): Welcome to the Backcountry Marketing Podcast. My name is Cool Hi, born, and I'll be your host today. This podcast dives deep with leaders of the outdoor marketing industry as they discuss the gritty details of their work, personal challenges and latest adventures, whether you're standing in the lift line, shuttling to fresh loam, or cracking a local beer. I hope you enjoyed today's episode. This is the Back Country Marketing Podcast. This episode is produced by Portside Productions, an outdoor, commercial and film production company based in the Pacific Northwest. Welcome to the Backcountry Marketing Podcast. My name is Cole Hoborne. Today I'm sitting down with Chris Dickerson, he's the director of Digital over at Verite Brand Communications. Chris, how are you doing?\n\nChris Dickerson (00:01:14): I'm doing great. Thanks for having me. How are you doing?\n\nCole Heilborn (00:01:17): Doing fantastic. Yeah, thanks for joining us today. Where are you located? Where are you calling in from?\n\nChris Dickerson (00:01:22): I am over in Seattle.\n\nCole Heilborn (00:01:26): Alright. All yeah. Rep in the Pacific Northwest.\n\nChris Dickerson (00:01:28): That's right.\n\nCole Heilborn (00:01:31): Well, I'm excited to have you on the show today. I think we've got a really fun topic that I'm excited to dive into. But if you wouldn't mind first just giving us a little bit of background on Verde, your role, and I guess a little bit of your history and where you've been and what you're up to now.", "token_estimate": 525, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:00:02", "end_timestamp": "00:01:31", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "774852be-1a67-40dc-ad40-244d4b020afc", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 1, "content": "Chris Dickerson (00:01:49): Sure. Yeah. So again, Chris Dickerson with Verde Brand Communications. I've been with Verde for about three years now. Before that, most of my experiences in skiing and snowboarding, I worked for Whistler Blackcomb for a number of years in sales and marketing. Worked in e-commerce at Zoomies, as well as retention marketing at evo. So I helped open stores there, manage email, so really e-commerce focused and SEO type stuff. From there, I hopped over to a creative agency for outdoor marketing, worked at social media agency with a good friend that I met at Evo, and then it ultimately went over to Verde. After I met Kristen, we shared some clients together with some past agencies. So I really sat in a brand position and a retailer position and an agency position. So I have three unique perspectives that I understand the forces that everybody has in their internal external teams from all sides of the table. (00:03:03): Yeah. And ultimately applying what I learned at all those other places to PR and really looking at how PR has evolved over the past. Kristen Carpenter created Verde about 20 years ago. This is our 20th anniversary actually on Durango, Colorado, and she's expanded. So we're about 20 people. Most of our people have roots in journalism, our media background. So I'd say a lot of us are editors and writers at heart, and we all love the outdoor space and specialty retail and kind of put those two together and that's a verde. So we try to be pretty dynamic and nimble with the changing landscape and how media is what they're writing about, what's dictating, what they're writing about, and then how we can make sure that our products and our clients are fitting what the editors and publishers are looking for.\n\nCole Heilborn (00:04:03): Sure. And I guess to give a quick shout out, you guys also run a podcast, the Channel Mastery podcast. I feel like it's one of the, I dunno if it's the original, but it seems like it's one of the legacy business podcasts in the outdoor industry. How long have you guys been running that?", "token_estimate": 521, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:01:49", "end_timestamp": "00:04:03", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "5f2c3720-f321-43f7-aa7e-136a156abbd2", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 2, "content": "Chris Dickerson (00:04:22): Yeah, so Kristen's podcast is Channel Mastery. Gosh, she's been doing it for three or four years now. I think we're in the upper hundreds of episodes now. It's about once a week it comes out and we've got some pretty cool ones coming down the pipeline that we prerecorded. So I recommend checking those out. But that really goes back to Kristen's roots and writing for papers and magazines where she just wants to continue to be in it and really understanding how business is changing. And we want to make sure that our specialty brands and our specialty retailers have the tools that they need to compete and be relevant and stay up to date with the latest technology.\n\nCole Heilborn (00:05:11): So for our time today, I'd love to talk about going to market, going to market strategies. It sounds like that can be a pretty overwhelming process. There's a lot of moving pieces, a lot of dates, a lot of timelines, a lot of partners and people all involved, manufacturers, and you've done a number of these different go-to-market strategies being a part of them, helping lead them. It sounds like one of the projects you were a part of was working with Hydro Floss to launch their growler. So I'd love if we could just kind of dive into that project and start there.", "token_estimate": 324, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:04:22", "end_timestamp": "00:05:11", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "9f67237c-fdf5-4807-b746-573d08f85cf4", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 3, "content": "Chris Dickerson (00:05:45): Sure, yeah, no problem. Yeah, I tend to go back to how Hydro Flask operates when at a previous agency, creative agency that I worked with, we were the agency of record for Hydro Flask at the time, and we really helped bring several of their products to market, and I thought they did a really good job of understanding the product lifestyle and the consumer lifestyle and understanding what the product was, and then creating that customer persona and the profile to match those two together to make sure when they were ready to launch and go to market, they had everything, all their ducks in the line and all their channels built to have a really successful launch. And they were one of the few companies I've worked with, many companies over the years that have not necessarily always done that and haven't had the most successful launches. So I always felt they were pretty dialed in that realm of things. There's been other brands, like Oakley has had some really successful launches when I was at Evo, and the way they coordinated all the players and the movers and shakers really were super impactful on driving sales as well as customer growth.\n\nSpeaker 3 (00:07:04): Gotcha.\n\nChris Dickerson (00:07:06): What was unique about that Growler was the fact when they plan out pretty far ahead of time, and I think that's pretty common in outdoor, especially with manufacturing.\n\nCole Heilborn (00:07:20): Are we talking like a year, two years?", "token_estimate": 369, "speakers": ["Chris Dickerson", "Speaker 3", "Cole Heilborn"], "start_timestamp": "00:05:45", "end_timestamp": "00:07:20", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "2d2476bc-9642-4663-9cc2-49e5f222b2a6", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 4, "content": "Chris Dickerson (00:07:23): Yeah, exactly. (00:07:24): So in those cycles are becoming smaller and smaller, but you're still one to two years out with your product development team and understanding what's coming down the pipeline, who your audience is as the launch gets closer and closer is really important to plan out that calendar. So when do you introduce the product to your marketing team, your sales team? When do you introduce it to your retailers, your wholesalers, or if your D two C, when do you start talking about that online and then start piecing those back to, okay, which marketing channels do I need to pull and activate to get in front of each one of those people or those audiences to make sure they're informed on what's coming down the pipeline and how they're talking about it. So we're all aligned with our messaging, and I think that's something really important to plan out from just a calendar point of view. And it seems pretty common sense, but it's often overlooked. (00:08:33): So once you figure out who each one of these subsets are, which levers you're pulling and when you're pulling it, so that's sort of your step one. And that can be repeated, that can be a step in repeat for each new product launch. But then when you look at the specific product, it's really important to look at, okay, who's the product for? What are the features and benefits, what's really the positioning of it? And I think we'll get into positioning a little bit more for each one of those products on what those key points are I, and then also looking at your revenue forecasting for each one of your channels. So obviously your retailers are going to have a certain amount of inventory. Your D two C channel is going to have to have certain sort of inventory, so understanding what's just your basic forecasting. (00:09:32): And larger companies obviously have full teams that do your planning and demand planning. It's a lot harder for smaller brands. You don't even know where to begin. And especially if you're a startup, you're like, how much of my traffic is coming from organic versus paid versus media and that social media, so on and so forth. So that can be really hard to figure out. And so you just almost have to start someplace and looking at how much traffic are you getting to your website now? What's your current conversion rate? How much traffic do I need to drive to my site to hit that conversion rate? And then you can even use those figures just to start with some really top line goals to hit for your product.", "token_estimate": 638, "speakers": ["Chris Dickerson"], "start_timestamp": "00:07:23", "end_timestamp": "00:07:23", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "85f4d2b7-bbf2-454b-ac7a-628dbb65a73a", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 5, "content": "Cole Heilborn (00:10:18): I see, I see. Okay. So I'm still trying to understand, so with this Growler Hydro Flask came to you guys and they said, here's our product. Here's all the features and benefits, and here are our customer personas, or did you help them develop those personas and those features and benefits?\n\nChris Dickerson (00:10:36): We helped them develop all of that. Their product team had the Growler, they told us what all the features and benefits were, and then they basically said, how do we bring this to life? That's when we really started digging into, okay, the position of the product. You also want to make sure that when you're thinking about the position of the product, that it all rolls back up to your brand. So you want to make sure that you're within your brand guidelines and it makes sense and it all will ladder back up to your full branding. So we really looked at the who's it for figuring out really, okay, who's going to use this? Who's our main customer? Are there any adjacent customers? So is everybody going to use a Growler for beer? Probably, but they also might use it for water or some other thing. So there could be other uses for that. That's also really important once you figure out who your end consumer is, how you are marketing to those people differently even though it's the same product. So really looking at the products and the features and the benefits, I like to look at a positioning statement of what that is, and then really laddering up to what the overt benefit is. What that is, is the what's in it for me.\n\nSpeaker 4 (00:12:08): Okay,", "token_estimate": 401, "speakers": ["Cole Heilborn", "Chris Dickerson", "Speaker 4"], "start_timestamp": "00:10:18", "end_timestamp": "00:12:08", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "f7700765-5d73-4354-9982-7cddb302337f", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 6, "content": "Chris Dickerson (00:12:08): If you can't answer the what's in it for me, for your customer, then you should probably start over because at the end of the day, we're all selfish and really want to know, why should I buy this? How is this going to add value to my life or my trip or whatever it is. And it's another thing that a lot of companies and brands won't be able to answer because they haven't thought about it. And you get wrapped up with all the fun campaign stuff of it. You forget about the product and the end user. And while when you're writing a positioning statement, you're really looking at, okay, what is this product? Who is it for? And what do they get out of it? And really that overt benefit should just be a really simple phrase of answering the what's in it for me question. And oftentimes when I ask my team or the clients I work with, it can stop them in their tracks. They haven't thought about it. And I thought Hydro Flask did a really good job of doing specifically that, always asking what's in it for the customer? What's the overt benefit?\n\nCole Heilborn (00:13:25): So what is that simple tagline for the Growler project,", "token_estimate": 289, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:12:08", "end_timestamp": "00:13:25", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "465ab0dc-fe76-4396-b96b-f592645d1547", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 7, "content": "Chris Dickerson (00:13:29): What we came up with for Hydro Flask, for the Growler, sort of the overt benefit, the what's in it for you is a hundred percent tap fresh beer regardless of location. Once we had that sort of succinct phrase, then we could build content off of that. So knowing that we really wanted this to be for the outdoor consumer who wanted just super fresh beer, fully carbonated, cold, wherever, that's what the campaign needed to roll out to be. And what's really nice when you put this all together in a deck with the features and the benefits and the overt benefit for the customer and the positioning statement, you can use that deck for your sales teams, for your marketing team, you put it together with a nice mood board and really build out this, keep it to less than 10 pages, basically be really succinct in what you're doing. And then once you have that all together with some critical thought, and you also want to put some supporting pillars in there, so how do you support that overt benefit, that a hundred percent fresh beer wherever you are\n\nCole Heilborn (00:14:49): Related to features,\n\nChris Dickerson (00:14:51): Features, benefits, and how that ties back to it.\n\nCole Heilborn (00:14:56): I see. So in the case of hydro floss, that would be a double insulated wall, the carrying capacity, things like that.\n\nChris Dickerson (00:15:02): Yeah, absolutely. Anything along those lines.\n\nCole Heilborn (00:15:04): Okay.\n\nChris Dickerson (00:15:05): So those are super helpful because then again, out to the sales team, if all your reps are out in retailers, they're all saying the same exact thing and teaching the same thing. So those are really handy for customer service reps to know to sell when their customers have questions, and that's sort of the very first part of bringing that product to life.", "token_estimate": 461, "speakers": ["Chris Dickerson", "Cole Heilborn"], "start_timestamp": "00:13:29", "end_timestamp": "00:15:05", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "38a7b0e3-07ed-4c21-86c3-95f55db1e28d", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 8, "content": "Cole Heilborn (00:15:29): Okay. Okay. I know I don't want to get us off track, but I'm really curious because you're saying the first thing that you need to do as the client or the partner who's working with the client is understand why is this product in existence? What are we solving? So it sounds like you have the positioning statement, and then from there you have to develop goals for each of, well, I guess all the components, right? For your customer, your audience, any product goals, brand goals, I guess, what are some examples of those goals for something that's maybe a little more elusive?", "token_estimate": 151, "speakers": ["Cole Heilborn"], "start_timestamp": "00:15:29", "end_timestamp": "00:15:29", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}, {"id": "c5f7b552-6a01-4c8f-9e6c-a619ba9e02a1", "episode_id": "888d9ad4-2113-48f1-81fc-b43da6280556", "cms_item_id": "68225dfc7bb476527f8c4865", "chunk_index": 9, "content": "Chris Dickerson (00:16:08): Sure. So I'll start with more of the quantitative goals. I'm more of a quantitative person, so that makes a little bit more sense to me. I'll look at traffic acquisition, email acquisition, product detail pages are like, okay, what are the goals that it can have from a number standpoint, an analytics standpoint, as well as more of a tangible, a product detail page type of box that you can check. So when I look at that, again, I list all of this out and it's like, okay, if I've got my product detail page, what goes on the product detail page, and then you check all your boxes, you've got your images, your product images, your product videos, any sort of how-tos, you've got your features and benefits and your descriptions. So I really like starting there after you do your positioning statement, if I can build out a really good product detail page with a good story behind it, that's going to be your hardest working page on your entire website is that product detail page. You don't know where people are going to come in from all your channels, whether it's paid social email, media, somebody might not even have any idea who or what your brand is. But if you've got a really solid product detail page and they were searching and found you on Google, you've got to be able to have that person understand who you are, what your brand is, buy into you all within that one page, (00:17:52): And to get them to add to cart basically. So if you think about that, okay, what do I need to support all of that, that wrap up to that positioning, that strategy, then from there I kind of work my way out. So where is the product going to be displayed on my website? Zoom's was kind of a fun website to work on because their whole philosophy, all their stores by design, it looked like they're a messed up kids' room. And the website is kind of similar where you'll have banners placed pretty strategically. So when you're browsing, you kind of find something that you might not necessarily see and you stumble upon it. So where am I marketing within my own website? Is it on the homepage category page? What image is displayed? And Google is getting really good at allowing people to AB test certain things. (00:18:58): So that's another thing that should be on that plan is EB testing opportunities. Is it a lifestyle image versus a product shot on a white? There's just so many things to think about. If it's a shoe, if you take a van's slip on, it's the same shoe in 30 different colors, but if you have a landing page that has one black van's shoes, it doesn't look so captivating. But if you have a category page that has every single color of the same shoe, that's a different way to merchandise that product. And it looks like you've got way more inventory to the consumer. So there's lots of fun things you could do to figure out, okay, how do I display this on my site? And then as you wire frame all of that out, then you can really start putting together your content plan for your video content and your photography content and how those fit into each one of these wireframe spots on your website.", "token_estimate": 785, "speakers": ["Chris Dickerson"], "start_timestamp": "00:16:08", "end_timestamp": "00:16:08", "podcast_index": 67, "episode_name": "EP 67: Chris Dickerson | Go-to-Market | Verde Brand Communications", "slug": "ep-67-chris-dickerson-go-to-market-verde-brand-communications", "web_url": "https://www.portsidepro.com/podcast-feed/ep-67-chris-dickerson-go-to-market-verde-brand-communications", "guest_name": "Chris Dickerson", "guest_title": "Director of Digital, Verde Brand Communications", "categories": [], "short_description": "How do you bring a product to life?", "podcast_length": "44:89"}]
